@import "tailwindcss";
@import "tw-animate-css";
@import "shadcn/tailwind.css";
@import "@fontsource-variable/geist";

@custom-variant dark (&:is(.dark *));

:root {
  color-scheme: dark;
  font-synthesis: none;
  text-rendering: optimizeLegibility;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  -webkit-text-size-adjust: 100%;
  --panel-bg: rgba(6, 13, 21, 0.86);
  --panel-bg-soft: rgba(136, 166, 198, 0.05);
  --panel-border: rgba(118, 154, 190, 0.13);
  --text-primary: #f3f7fb;
  --text-secondary: #bac5d1;
  --text-muted: #7a8796;
  --market-up: #c84f4f;
  --market-down: #118866;
  --risk-rise: #c84f4f;
  --risk-fall: #118866;
  --green: var(--market-down);
  --yellow: #b8a35d;
  --blue: #7897b4;
  --red: var(--market-up);
  --green-rgb: 17, 136, 102;
  --yellow-rgb: 184, 163, 93;
  --blue-rgb: 120, 151, 180;
  --red-rgb: 200, 79, 79;
  --line-soft: rgba(118, 154, 190, 0.1);
  --line-visible: rgba(20, 160, 111, 0.18);
  --surface-quiet: rgba(136, 166, 198, 0.05);
  --surface-lift: rgba(136, 166, 198, 0.075);
  --surface-glass: rgba(8, 15, 24, 0.74);
  --terminal-grid: rgba(92, 119, 146, 0.06);
  --amber-glow: rgba(215, 196, 111, 0.16);
  --window-drag-height: 42px;
  --window-chrome-bg: rgba(4, 9, 14, 0.97);
  --config-drawer-height: min(660px, calc(100dvh - var(--window-drag-height) - 32px));
  --scrollbar-size: 3px;
  --scrollbar-thumb: rgba(110, 128, 146, 0.16);
  --scrollbar-thumb-hover: rgba(122, 141, 162, 0.3);
  --scrollbar-track: transparent;
  scrollbar-color: var(--scrollbar-thumb) var(--scrollbar-track);
  scrollbar-width: thin;
  --background: oklch(1 0 0);
  --foreground: oklch(0.145 0 0);
  --card: oklch(1 0 0);
  --card-foreground: oklch(0.145 0 0);
  --popover: oklch(1 0 0);
  --popover-foreground: oklch(0.145 0 0);
  --primary: oklch(0.205 0 0);
  --primary-foreground: oklch(0.985 0 0);
  --secondary: oklch(0.97 0 0);
  --secondary-foreground: oklch(0.205 0 0);
  --muted: oklch(0.97 0 0);
  --muted-foreground: oklch(0.556 0 0);
  --accent: oklch(0.97 0 0);
  --accent-foreground: oklch(0.205 0 0);
  --destructive: oklch(0.577 0.245 27.325);
  --border: oklch(0.922 0 0);
  --input: oklch(0.922 0 0);
  --ring: oklch(0.708 0 0);
  --chart-1: oklch(0.87 0 0);
  --chart-2: oklch(0.556 0 0);
  --chart-3: oklch(0.439 0 0);
  --chart-4: oklch(0.371 0 0);
  --chart-5: oklch(0.269 0 0);
  --radius: 0.625rem;
  --sidebar: oklch(0.985 0 0);
  --sidebar-foreground: oklch(0.145 0 0);
  --sidebar-primary: oklch(0.205 0 0);
  --sidebar-primary-foreground: oklch(0.985 0 0);
  --sidebar-accent: oklch(0.97 0 0);
  --sidebar-accent-foreground: oklch(0.205 0 0);
  --sidebar-border: oklch(0.922 0 0);
  --sidebar-ring: oklch(0.708 0 0);
}

html[data-rportfolio-style="light"] {
  color-scheme: light;
  --panel-bg: rgba(255, 255, 255, 0.86);
  --panel-bg-soft: rgba(31, 37, 48, 0.035);
  --panel-border: rgba(42, 82, 132, 0.14);
  --text-primary: #172133;
  --text-secondary: #58667c;
  --text-muted: #6f7e94;
  --market-up: #c43f38;
  --market-down: #0f8f62;
  --risk-rise: #c43f38;
  --risk-fall: #0f8f62;
  --green: var(--market-down);
  --yellow: #96741a;
  --blue: #2563eb;
  --red: var(--market-up);
  --green-rgb: 15, 143, 98;
  --yellow-rgb: 150, 116, 26;
  --blue-rgb: 37, 99, 235;
  --red-rgb: 196, 63, 56;
  --line-soft: rgba(42, 82, 132, 0.12);
  --line-visible: rgba(37, 99, 235, 0.2);
  --surface-quiet: rgba(31, 37, 48, 0.035);
  --surface-lift: rgba(37, 99, 235, 0.058);
  --surface-glass: rgba(255, 255, 255, 0.78);
  --terminal-grid: rgba(42, 82, 132, 0.032);
  --amber-glow: rgba(37, 99, 235, 0.14);
  --window-chrome-bg: rgba(244, 247, 251, 0.97);
  --scrollbar-thumb: rgba(82, 101, 126, 0.16);
  --scrollbar-thumb-hover: rgba(82, 101, 126, 0.28);
  --scrollbar-track: transparent;
  scrollbar-color: var(--scrollbar-thumb) var(--scrollbar-track);
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

html,
body,
#root {
  height: 100%;
  margin: 0;
}

body {
  overflow: hidden;
  background:
    linear-gradient(180deg, rgba(12, 24, 36, 0.9), rgba(5, 12, 20, 0.42) 44%, rgba(3, 6, 10, 0) 72%),
    linear-gradient(120deg, rgba(42, 72, 105, 0.13), rgba(20, 160, 111, 0.028) 48%, transparent 72%),
    linear-gradient(var(--terminal-grid) 1px, transparent 1px),
    linear-gradient(90deg, rgba(92, 119, 146, 0.05) 1px, transparent 1px),
    radial-gradient(circle at 48% 0%, rgba(132, 167, 207, 0.08), transparent 30%),
    linear-gradient(180deg, #07111a 0%, #050b12 58%, #03070c 100%);
  background-size: auto, auto, 32px 32px, 32px 32px, auto, auto;
}

.window-drag-region {
  position: fixed;
  z-index: 30;
  inset: 0 0 auto;
  height: var(--window-drag-height);
  background: var(--window-chrome-bg);
  border-bottom: 1px solid var(--line-soft);
  user-select: none;
}

.window-titlebar-actions {
  position: fixed;
  z-index: 42;
  top: calc((var(--window-drag-height) - 30px) / 2);
  right: 10px;
  display: inline-flex;
  align-items: center;
  justify-content: flex-end;
  gap: 6px;
  max-width: calc(100vw - 120px);
}

.rail-collapse-titlebar-button.MuiIconButton-root {
  width: 28px;
  height: 28px;
  display: grid;
  place-items: center;
  padding: 0;
  border: 1px solid rgba(129, 144, 164, 0.12);
  border-radius: 8px;
  color: rgba(183, 191, 203, 0.82);
  background:
    linear-gradient(180deg, rgba(127, 159, 194, 0.06), rgba(127, 159, 194, 0.018)),
    rgba(9, 13, 20, 0.42);
  box-shadow:
    inset 0 1px 0 rgba(226, 235, 247, 0.055),
    0 5px 12px rgba(0, 0, 0, 0.12);
  cursor: pointer;
  touch-action: manipulation;
  transition:
    border-color 150ms ease,
    background-color 150ms ease,
    color 150ms ease,
    transform 150ms ease;
}

.rail-collapse-titlebar-button.MuiIconButton-root:hover {
  color: var(--text-primary);
  border-color: rgba(136, 154, 177, 0.22);
  background:
    linear-gradient(180deg, rgba(127, 159, 194, 0.095), rgba(127, 159, 194, 0.026)),
    rgba(12, 18, 26, 0.62);
}

.rail-collapse-titlebar-button.MuiIconButton-root:focus-visible {
  outline: 0;
  border-color: rgba(var(--green-rgb), 0.34);
  box-shadow: 0 0 0 3px rgba(var(--green-rgb), 0.12);
}

.rail-collapse-icon {
  position: relative;
  width: 16px;
  height: 16px;
  display: block;
  border: 1.6px solid currentColor;
  border-radius: 4px;
  opacity: 0.95;
}

.rail-collapse-icon span {
  position: absolute;
  top: 3px;
  bottom: 3px;
  width: 1.6px;
  border-radius: 999px;
  background: currentColor;
}

.rail-collapse-icon.is-left span {
  left: 4px;
}

.rail-collapse-icon.is-right span {
  right: 4px;
}

html[data-rportfolio-style="light"] body {
  --panel-bg: rgba(255, 255, 255, 0.86);
  --panel-bg-soft: rgba(31, 37, 48, 0.035);
  --panel-border: rgba(42, 82, 132, 0.14);
  --text-primary: #172133;
  --text-secondary: #58667c;
  --text-muted: #6f7e94;
  --line-soft: rgba(42, 82, 132, 0.12);
  --line-visible: rgba(37, 99, 235, 0.2);
  --surface-quiet: rgba(31, 37, 48, 0.035);
  --surface-lift: rgba(37, 99, 235, 0.058);
  --surface-glass: rgba(255, 255, 255, 0.78);
  color: var(--text-primary);
  background:
    linear-gradient(180deg, rgba(248, 251, 255, 0.92), rgba(244, 247, 251, 0.18) 42%, rgba(238, 243, 249, 0) 70%),
    linear-gradient(120deg, rgba(37, 99, 235, 0.032), rgba(42, 82, 132, 0.022) 46%, transparent 70%),
    linear-gradient(var(--terminal-grid) 1px, transparent 1px),
    linear-gradient(90deg, rgba(42, 82, 132, 0.032) 1px, transparent 1px),
    linear-gradient(180deg, #f4f7fb 0%, #eef3f9 100%);
  background-size: auto, auto, 32px 32px, 32px 32px, auto;
}

button,
input,
select {
  font: inherit;
}

*::-webkit-scrollbar {
  width: var(--scrollbar-size);
  height: var(--scrollbar-size);
}

*::-webkit-scrollbar-thumb {
  border-radius: 999px;
  background: var(--scrollbar-thumb);
  border: 0;
  box-shadow: none;
}

*::-webkit-scrollbar-thumb:hover {
  background: var(--scrollbar-thumb-hover);
}

*::-webkit-scrollbar-track {
  background: var(--scrollbar-track);
}

.app-shell {
  height: 100%;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 10px;
  padding: calc(var(--window-drag-height) + 12px) 4px 12px 16px;
  overflow: hidden;
}

.topbar-content {
  padding: 0 !important;
}

.topbar-card {
  flex: 0 0 auto;
  overflow: visible;
  border: 0 !important;
  background: transparent !important;
  box-shadow: none !important;
}

.topbar-layout {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  align-items: center;
  gap: 12px;
  min-width: 0;
}

.brand-block {
  display: flex;
  align-items: center;
  gap: 10px;
  min-width: 0;
}

.brand-mark {
  width: 48px;
  height: 48px;
  display: grid;
  place-items: center;
  border-radius: 10px;
  background:
    linear-gradient(145deg, rgba(255, 255, 255, 0.28), rgba(255, 255, 255, 0.04)),
    #171717;
  border: 1px solid rgba(255, 255, 255, 0.14);
  color: #f8f8f4;
  font-weight: 900;
  letter-spacing: 0;
  box-shadow:
    0 18px 34px rgba(0, 0, 0, 0.42),
    inset 0 1px 0 rgba(255, 255, 255, 0.28);
}

.brand-copy {
  display: grid;
  gap: 2px;
}

.brand-title {
  color: var(--text-primary);
  font-size: 1.25rem;
  line-height: 1;
}

.brand-subtitle {
  color: var(--text-muted);
  font-size: 0.78rem;
  font-weight: 760;
  letter-spacing: 0;
  text-transform: none;
}

.topbar-controls {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 8px;
  min-width: 0;
  max-width: 100%;
  flex-wrap: nowrap;
  padding: 0;
  border: 0;
  background: transparent;
  box-shadow: none;
}

.profile-select {
  width: clamp(230px, 24vw, 340px);
  min-width: 230px;
  max-width: 340px;
}

.source-select {
  width: 112px;
  min-width: 112px;
}

.titlebar-field.source-select {
  width: 118px;
  min-width: 0;
  max-width: 128px;
}

.titlebar-field .MuiOutlinedInput-root {
  height: 30px;
  border-radius: 8px;
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.045), rgba(255, 255, 255, 0.01)),
    rgba(8, 9, 9, 0.48);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.05),
    0 6px 14px rgba(0, 0, 0, 0.14);
}

.titlebar-field .MuiSelect-select {
  padding-top: 4px;
  padding-bottom: 4px;
  font-size: 0.68rem;
}

.titlebar-icon-button.MuiIconButton-root {
  width: 30px;
  height: 30px;
  border-radius: 8px;
  border: 1px solid rgba(var(--green-rgb), 0.14);
  color: var(--text-primary);
  background:
    linear-gradient(180deg, rgba(var(--green-rgb), 0.07), rgba(255, 255, 255, 0.012)),
    rgba(8, 8, 8, 0.5);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.06),
    0 6px 14px rgba(0, 0, 0, 0.14);
}

.titlebar-icon-button.MuiIconButton-root:hover {
  border-color: rgba(var(--green-rgb), 0.26);
  background:
    linear-gradient(180deg, rgba(var(--green-rgb), 0.14), rgba(var(--green-rgb), 0.028)),
    rgba(14, 14, 14, 0.82);
}

.titlebar-icon-button .MuiSvgIcon-root {
  font-size: 0.95rem;
}

.rail-collapse-titlebar-button.MuiIconButton-root {
  width: 28px;
  height: 28px;
  border-color: rgba(129, 144, 164, 0.12);
  color: rgba(190, 199, 213, 0.9);
  background:
    linear-gradient(180deg, rgba(127, 159, 194, 0.06), rgba(127, 159, 194, 0.018)),
    rgba(9, 13, 20, 0.42);
  box-shadow:
    inset 0 1px 0 rgba(226, 235, 247, 0.055),
    0 5px 12px rgba(0, 0, 0, 0.12);
}

.rail-collapse-titlebar-button.MuiIconButton-root:hover {
  color: var(--text-primary);
  border-color: rgba(136, 154, 177, 0.22);
  background:
    linear-gradient(180deg, rgba(127, 159, 194, 0.095), rgba(127, 159, 194, 0.026)),
    rgba(12, 18, 26, 0.62);
}

.rail-collapse-titlebar-button.is-collapsed .rail-collapse-icon span {
  opacity: 0.5;
}

.date-field {
  width: 154px;
}

.market-date-trigger {
  height: 38px;
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  align-items: center;
  gap: 8px;
  padding: 0 11px;
  border: 1px solid rgba(255, 255, 255, 0.13);
  border-radius: 10px;
  color: var(--text-primary);
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.046), rgba(255, 255, 255, 0.012)),
    rgba(8, 9, 9, 0.58);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.055),
    0 10px 24px rgba(0, 0, 0, 0.18);
  cursor: pointer;
  transition:
    border-color 160ms ease,
    background-color 160ms ease,
    box-shadow 160ms ease,
    transform 160ms ease;
}

.market-date-trigger:hover,
.market-date-trigger.is-open {
  border-color: rgba(var(--green-rgb), 0.24);
  background:
    linear-gradient(180deg, rgba(var(--green-rgb), 0.08), rgba(255, 255, 255, 0.016)),
    rgba(10, 12, 12, 0.76);
}

.market-date-trigger:focus-visible {
  outline: 0;
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.08),
    0 0 0 2px rgba(var(--green-rgb), 0.22),
    0 10px 24px rgba(0, 0, 0, 0.18);
}

.market-date-trigger .MuiSvgIcon-root {
  color: rgba(243, 240, 233, 0.78);
  font-size: 0.92rem;
}

.market-date-value {
  min-width: 0;
  display: inline-flex;
  align-items: baseline;
  overflow: hidden;
  white-space: nowrap;
}

.market-date-value strong {
  color: rgba(246, 251, 245, 0.94);
  font-size: 0.82rem;
  font-weight: 860;
  line-height: 1;
}

.market-date-value em {
  color: rgba(246, 251, 245, 0.88);
  font-size: 0.82rem;
  font-style: normal;
  font-weight: 860;
  line-height: 1;
}

.market-date-popover-paper.MuiPaper-root {
  width: min(276px, calc(100vw - 24px));
  margin-top: 8px;
  overflow: hidden;
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: 11px;
  color: var(--text-primary);
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.058), rgba(255, 255, 255, 0.014)),
    linear-gradient(135deg, rgba(var(--green-rgb), 0.065), rgba(var(--yellow-rgb), 0.028) 45%, rgba(0, 0, 0, 0.04)),
    rgba(8, 9, 9, 0.96);
  box-shadow:
    0 18px 48px rgba(0, 0, 0, 0.46),
    inset 0 1px 0 rgba(255, 255, 255, 0.08);
  backdrop-filter: blur(18px);
  -webkit-backdrop-filter: blur(18px);
}

.market-date-panel {
  display: grid;
  gap: 8px;
  padding: 10px;
}

.market-date-panel-head {
  display: grid;
  grid-template-columns: 30px minmax(0, 1fr) 30px;
  align-items: center;
  gap: 7px;
}

.market-date-panel-head > div {
  min-width: 0;
  display: grid;
  gap: 2px;
  text-align: center;
}

.market-date-panel-head strong {
  color: var(--text-primary);
  font-size: 0.9rem;
  font-weight: 900;
  line-height: 1.1;
}

.market-date-panel-head span {
  color: var(--text-muted);
  font-size: 0.62rem;
  font-weight: 900;
}

.market-date-nav,
.market-date-day,
.market-date-footer button {
  border: 0;
  color: inherit;
  background: transparent;
  cursor: pointer;
}

.market-date-nav {
  width: 30px;
  height: 30px;
  display: grid;
  place-items: center;
  border-radius: 8px;
  color: var(--text-secondary);
  font-size: 1.12rem;
}

.market-date-nav:hover {
  color: var(--text-primary);
  background: rgba(255, 255, 255, 0.06);
}

.market-date-weekdays,
.market-date-grid {
  display: grid;
  grid-template-columns: repeat(7, minmax(0, 1fr));
}

.market-date-weekdays {
  gap: 3px;
  padding: 2px 2px 0;
}

.market-date-weekdays span {
  color: var(--text-muted);
  font-size: 0.66rem;
  font-weight: 900;
  text-align: center;
}

.market-date-grid {
  gap: 3px;
}

.market-date-day {
  position: relative;
  height: 30px;
  display: grid;
  place-items: center;
  border-radius: 7px;
  color: rgba(246, 242, 232, 0.82);
  font-size: 0.76rem;
  font-weight: 820;
  line-height: 1;
  transition:
    color 140ms ease,
    background-color 140ms ease,
    box-shadow 140ms ease,
    transform 140ms ease;
}

.market-date-day:hover {
  color: var(--text-primary);
  background: rgba(255, 255, 255, 0.052);
}

.market-date-day:focus-visible {
  outline: 0;
  box-shadow: 0 0 0 2px rgba(var(--green-rgb), 0.26);
}

.market-date-day.is-selected {
  color: #06120e;
  background:
    linear-gradient(180deg, rgba(236, 216, 127, 0.72), rgba(var(--green-rgb), 0.78));
  box-shadow:
    0 8px 18px rgba(var(--green-rgb), 0.16),
    inset 0 1px 0 rgba(255, 255, 255, 0.36);
}

.market-date-day.is-today:not(.is-selected) {
  color: #ead66f;
  box-shadow: inset 0 0 0 1px rgba(var(--yellow-rgb), 0.2);
}

.market-date-day.is-outside {
  color: rgba(210, 201, 191, 0.28);
}

.market-date-day.is-weekend {
  color: rgba(210, 201, 191, 0.26);
  cursor: not-allowed;
}

.market-date-day.is-weekend:hover {
  background: transparent;
}

.market-date-day i {
  position: absolute;
  bottom: 4px;
  width: 3px;
  height: 3px;
  border-radius: 999px;
  background: currentColor;
}

.market-date-footer {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 5px;
  padding-top: 2px;
}

.market-date-footer button {
  min-width: 0;
  height: 29px;
  border: 1px solid rgba(255, 255, 255, 0.09);
  border-radius: 8px;
  color: var(--text-secondary);
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.048), rgba(255, 255, 255, 0.01)),
    rgba(0, 0, 0, 0.18);
  font-size: 0.62rem;
  font-weight: 900;
}

.market-date-footer button:hover {
  color: var(--text-primary);
  border-color: rgba(var(--green-rgb), 0.18);
  background: rgba(var(--green-rgb), 0.07);
}

.topbar-field .MuiOutlinedInput-root {
  height: 38px;
  border-radius: 10px;
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.046), rgba(255, 255, 255, 0.012)),
    rgba(8, 9, 9, 0.58);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.055),
    0 10px 24px rgba(0, 0, 0, 0.18);
  transition:
    border-color 160ms ease,
    background-color 160ms ease,
    box-shadow 160ms ease;
}

.topbar-field .MuiOutlinedInput-root:hover {
  background-color: rgba(255, 255, 255, 0.034);
}

.topbar-field .MuiOutlinedInput-root.Mui-focused {
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.08),
    0 0 0 1px rgba(243, 240, 233, 0.08),
    0 10px 24px rgba(0, 0, 0, 0.18);
}

.topbar-field .MuiOutlinedInput-notchedOutline {
  border-color: rgba(255, 255, 255, 0.13);
}

.topbar-field .MuiOutlinedInput-root:hover .MuiOutlinedInput-notchedOutline,
.topbar-field .MuiOutlinedInput-root.Mui-focused .MuiOutlinedInput-notchedOutline {
  border-color: rgba(243, 240, 233, 0.25);
}

.topbar-field .MuiInputBase-input,
.topbar-field .MuiSelect-select {
  color: var(--text-primary);
  font-size: 0.82rem;
  font-weight: 860;
  letter-spacing: 0;
}

.topbar-field .MuiSelect-select {
  padding-top: 7px;
  padding-bottom: 7px;
}

