.decision-workspace {
  flex: 1 1 0;
  min-width: 0;
  min-height: 0;
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  grid-template-rows: minmax(0, 1fr);
  gap: 12px;
  padding-bottom: 0;
  overflow: hidden;
  overscroll-behavior: contain;
}

.decision-workspace.is-right-rail-collapsed {
  grid-template-columns: minmax(0, 1fr);
}

.decision-main-scroll {
  grid-column: 1;
  grid-row: 1;
  min-width: 0;
  min-height: 0;
  display: grid;
  align-content: start;
  gap: 12px;
  padding: 0 8px 22px 0;
  overflow: auto;
  overscroll-behavior: contain;
  scrollbar-gutter: stable;
  scrollbar-color: rgba(107, 128, 150, 0.22) rgba(4, 9, 15, 0.16);
  scrollbar-width: thin;
}

.decision-main-scroll::-webkit-scrollbar,
.decision-rail::-webkit-scrollbar {
  width: 4px;
  height: 4px;
}

.decision-main-scroll::-webkit-scrollbar-track,
.decision-rail::-webkit-scrollbar-track {
  background: rgba(5, 11, 18, 0.18);
  border-radius: 999px;
}

.decision-main-scroll::-webkit-scrollbar-thumb {
  background: rgba(103, 128, 154, 0.24);
  border: 0;
  border-radius: 999px;
}

.decision-rail::-webkit-scrollbar-thumb {
  background: rgba(112, 121, 132, 0.24);
  border: 0;
  border-radius: 999px;
}

.decision-summary-panel,
.decision-rail,
.workbench-panel {
  border: 1px solid var(--panel-border);
  border-radius: 10px;
  background:
    linear-gradient(180deg, rgba(136, 166, 198, 0.055), rgba(20, 160, 111, 0.01)),
    var(--panel-bg);
  box-shadow:
    0 20px 54px rgba(0, 0, 0, 0.38),
    inset 0 1px 0 rgba(196, 220, 255, 0.06);
  backdrop-filter: blur(18px);
  -webkit-backdrop-filter: blur(18px);
}

.config-drawer-layer {
  position: fixed;
  inset: 0;
  z-index: 80;
  display: grid;
  place-items: center;
  padding: calc(var(--window-drag-height) + 14px) 18px 18px;
  visibility: hidden;
  pointer-events: none;
}

.config-drawer-layer.is-open {
  visibility: visible;
  pointer-events: auto;
}

.config-drawer-backdrop {
  position: fixed;
  inset: 0;
  border: 0;
  background:
    linear-gradient(90deg, rgba(0, 0, 0, 0.18), rgba(0, 0, 0, 0.52)),
    rgba(0, 0, 0, 0.34);
  opacity: 0;
  cursor: default;
  transition: opacity 180ms ease;
}

.config-drawer-layer.is-open .config-drawer-backdrop {
  opacity: 1;
}

.config-drawer {
  position: relative;
  width: min(980px, calc(100vw - 36px));
  height: var(--config-drawer-height);
  max-height: var(--config-drawer-height);
  display: grid;
  grid-template-rows: auto minmax(0, 1fr);
  overflow: hidden;
  border: 1px solid rgba(255, 255, 255, 0.13);
  border-radius: 12px;
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.058), rgba(255, 255, 255, 0.012)),
    rgba(7, 8, 8, 0.96);
  box-shadow:
    0 28px 90px rgba(0, 0, 0, 0.5),
    inset 0 1px 0 rgba(255, 255, 255, 0.08);
  backdrop-filter: blur(22px);
  -webkit-backdrop-filter: blur(22px);
  transform: translateY(12px) scale(0.985);
  opacity: 0;
  transition:
    transform 190ms ease,
    opacity 190ms ease;
}

.config-drawer-layer.is-open .config-drawer {
  transform: translateY(0) scale(1);
  opacity: 1;
}

.config-drawer-head {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  align-items: center;
  padding: 11px 14px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.09);
  background:
    linear-gradient(180deg, rgba(var(--green-rgb), 0.065), rgba(255, 255, 255, 0.012)),
    rgba(0, 0, 0, 0.18);
}

.config-drawer-head > div {
  min-width: 0;
  display: grid;
  gap: 3px;
}

.config-drawer-head span {
  color: var(--text-muted);
  font-size: 0.62rem;
  font-weight: 900;
  text-transform: uppercase;
}

.config-drawer-head strong {
  overflow: hidden;
  color: var(--text-primary);
  font-size: 0.9rem;
  font-weight: 950;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.config-drawer-head button {
  width: 34px;
  height: 34px;
  display: grid;
  place-items: center;
  border: 1px solid rgba(255, 255, 255, 0.11);
  border-radius: 9px;
  color: var(--text-secondary);
  background: rgba(255, 255, 255, 0.045);
