  color: var(--text-primary);
  font-size: 0.7rem;
  font-weight: 880;
  letter-spacing: 0;
  line-height: 1;
  text-transform: none;
  box-shadow: none;
  transition:
    border-color 150ms ease,
    background-color 150ms ease,
    color 150ms ease,
    transform 150ms ease;
}

.config-drawer .MuiButton-root.MuiButton-root:hover {
  transform: translateY(-1px);
  box-shadow: none;
}

.config-drawer .MuiButton-root.MuiButton-root:focus-visible {
  outline: 0;
  box-shadow: 0 0 0 3px rgba(var(--blue-rgb), 0.12);
}

.config-drawer .MuiButton-root.MuiButton-root.Mui-disabled {
  transform: none;
  color: var(--text-muted);
  border-color: rgba(255, 255, 255, 0.07);
  background: rgba(255, 255, 255, 0.026);
