    rgba(12, 12, 12, 0.66);
}

.config-global-grid span {
  color: var(--text-muted);
  font-size: 0.62rem;
  font-weight: 900;
  text-transform: uppercase;
}

.config-global-grid strong {
  overflow: hidden;
  color: var(--text-primary);
  font-size: 0.82rem;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.config-global-grid p {
  margin: 0;
  color: var(--text-secondary);
  font-size: 0.68rem;
