.decision-summary-panel {
  grid-column: 1;
  grid-row: 1;
  position: relative;
  display: grid;
  grid-template-columns: repeat(2, minmax(420px, 1fr));
  grid-template-areas:
    "heading advice"
    "protocol protocol"
    "copy evidence";
  gap: 8px 10px;
  min-width: 0;
  min-height: 418px;
  padding: 13px;
  overflow: hidden;
}

.decision-summary-panel::before {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  background:
    linear-gradient(115deg, rgba(var(--yellow-rgb), 0.06), rgba(var(--green-rgb), 0.032) 34%, transparent 66%),
    linear-gradient(90deg, rgba(255, 255, 255, 0.035), transparent 20%),
    repeating-linear-gradient(0deg, transparent 0 27px, rgba(255, 255, 255, 0.021) 28px 29px);
  opacity: 0.74;
}

.decision-summary-panel::after {
  content: "";
  position: absolute;
  top: 18px;
  bottom: 18px;
  left: 0;
  width: 3px;
  background: linear-gradient(180deg, var(--yellow), rgba(var(--green-rgb), 0.26), transparent);
  opacity: 0.64;
}

.decision-summary-panel.is-protocol-broken::after,
.decision-summary-panel.is-protocol-panic::after {
  background: linear-gradient(180deg, var(--red), transparent);
}

.decision-summary-panel.is-protocol-observe::after {
  background: linear-gradient(180deg, var(--yellow), rgba(var(--green-rgb), 0.22), transparent);
}

.decision-summary-panel.is-protocol-probe::after {
  background: linear-gradient(180deg, var(--green), rgba(var(--yellow-rgb), 0.24), transparent);
}

.decision-summary-panel.is-protocol-probe .decision-kicker,
.decision-summary-panel.is-protocol-probe .decision-heading h1 {
  color: rgba(230, 250, 239, 0.96);
}

.decision-summary-panel.is-protocol-probe .decision-copy-card.is-note {
  color: rgba(212, 236, 219, 0.92);
  background:
    linear-gradient(135deg, rgba(var(--green-rgb), 0.12), rgba(var(--yellow-rgb), 0.04)),
    rgba(8, 19, 22, 0.58);
  border-color: rgba(var(--green-rgb), 0.18);
}

.decision-summary-panel.is-protocol-probe .decision-copy-card.is-note strong {
  color: rgba(207, 238, 218, 0.94);
}

.decision-summary-panel.is-protocol-broken,
.decision-summary-panel.is-protocol-panic {
  min-height: 440px;
  border-color: rgba(var(--red-rgb), 0.22);
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.042), rgba(255, 255, 255, 0.01)),
    linear-gradient(110deg, rgba(var(--red-rgb), 0.046), transparent 38%),
    rgba(7, 8, 8, 0.85);
  box-shadow:
    0 18px 48px rgba(0, 0, 0, 0.42),
    inset 0 1px 0 rgba(255, 255, 255, 0.06),
    inset 0 0 0 1px rgba(var(--red-rgb), 0.035);
}

.decision-summary-panel.is-protocol-broken::before,
.decision-summary-panel.is-protocol-panic::before {
  background:
    linear-gradient(115deg, rgba(var(--red-rgb), 0.06), rgba(117, 132, 145, 0.03) 34%, transparent 68%),
    linear-gradient(90deg, rgba(255, 255, 255, 0.03), transparent 18%),
    repeating-linear-gradient(0deg, transparent 0 27px, rgba(255, 255, 255, 0.02) 28px 29px);
  opacity: 0.7;
}

.decision-summary-panel.is-protocol-broken .decision-wave,
.decision-summary-panel.is-protocol-panic .decision-wave {
  opacity: 0.22;
  filter: grayscale(1) saturate(0.55);
}

.decision-summary-panel.is-protocol-broken .wave-line,
.decision-summary-panel.is-protocol-panic .wave-line {
  stroke: rgba(225, 153, 153, 0.52);
  filter: drop-shadow(0 0 7px rgba(var(--red-rgb), 0.22));
}

.decision-summary-panel.is-protocol-broken .decision-kicker,
.decision-summary-panel.is-protocol-panic .decision-kicker {
  color: #cfa1a1;
}

.decision-summary-panel.is-protocol-broken .decision-heading h1,
.decision-summary-panel.is-protocol-panic .decision-heading h1 {
  color: #f1eded;
  text-shadow: 0 0 18px rgba(var(--red-rgb), 0.16);
}

.decision-summary-panel.is-protocol-broken .decision-context-card,
.decision-summary-panel.is-protocol-panic .decision-context-card {
  color: #ddcaca;
  background: rgba(var(--red-rgb), 0.055);
  border-color: rgba(var(--red-rgb), 0.16);
}

.decision-summary-panel.is-protocol-broken .decision-context-card.is-condition,
.decision-summary-panel.is-protocol-panic .decision-context-card.is-condition {
  color: #f0aaaa;
  background:
    linear-gradient(90deg, rgba(var(--red-rgb), 0.12), rgba(var(--red-rgb), 0.04));
}

.decision-wave {
  position: absolute;
  inset: 10px 286px auto auto;
  width: min(34%, 420px);
  height: 46%;
  opacity: 0.13;
  overflow: hidden;
  pointer-events: none;
}

.decision-wave svg {
  width: 100%;
  height: 100%;
  overflow: hidden;
}

.decision-wave path,
.decision-wave circle {
  vector-effect: non-scaling-stroke;
}

.wave-line {
  fill: none;
  stroke: rgba(215, 196, 111, 0.72);
  stroke-width: 1.42;
  filter: drop-shadow(0 0 7px var(--amber-glow));
}

.wave-line.is-soft {
  stroke: rgba(255, 255, 255, 0.12);
  stroke-width: 1;
  filter: none;
}

.wave-fill {
  fill: rgba(255, 255, 255, 0.018);
  stroke: none;
}

.decision-wave circle {
  fill: #ecd87f;
  filter: drop-shadow(0 0 8px rgba(var(--yellow-rgb), 0.42));
}

.decision-summary-panel > *:not(.decision-wave) {
  position: relative;
  z-index: 1;
}

.decision-heading,
.decision-evidence-panel,
.decision-protocol-panel,
.decision-copy-panel,
.decision-position-panel {
  min-width: 0;
  display: grid;
  gap: 8px;
  padding: 10px;
  border: 1px solid rgba(92, 119, 150, 0.18);
  border-radius: 9px;
  background:
    linear-gradient(145deg, rgba(28, 43, 59, 0.62), rgba(8, 16, 26, 0.24)),
    rgba(6, 12, 20, 0.46);
  box-shadow:
    inset 0 1px 0 rgba(210, 229, 255, 0.055),
    inset 0 -1px 0 rgba(0, 0, 0, 0.24);
}

.decision-section-label {
  min-width: 0;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  color: var(--text-muted);
  font-size: 0.62rem;
  font-weight: 900;
  line-height: 1.1;
}

.decision-section-label span,
.decision-section-label b {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.decision-section-label span {
  color: rgba(210, 222, 236, 0.82);
}

.decision-section-label b {
  color: rgba(218, 226, 239, 0.66);
  font-weight: 900;
}

.decision-heading {
  grid-area: heading;
  align-content: start;
  grid-template-rows: auto auto 1fr;
  background:
    radial-gradient(circle at 92% 5%, rgba(var(--yellow-rgb), 0.095), transparent 34%),
    linear-gradient(145deg, rgba(31, 44, 57, 0.7), rgba(8, 17, 28, 0.24)),
    rgba(7, 13, 20, 0.5);
}

.decision-title-row {
  min-width: 0;
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: start;
  gap: 10px;
}

.decision-title-row > div {
  min-width: 0;
}

.decision-heading .MuiChip-root {
  height: 28px;
  max-width: min(100%, 204px);
  justify-self: end;
  margin-top: 2px;
  padding: 0 5px;
  border-radius: 999px;
  color: #ffdf62 !important;
  background:
    linear-gradient(180deg, rgba(var(--yellow-rgb), 0.18), rgba(var(--yellow-rgb), 0.052)),
    rgba(26, 23, 10, 0.78) !important;
  border: 1px solid rgba(var(--yellow-rgb), 0.38);
  box-shadow:
    inset 0 1px 0 rgba(255, 247, 190, 0.18),
    0 0 0 1px rgba(var(--yellow-rgb), 0.055),
    0 10px 24px rgba(var(--yellow-rgb), 0.08);
}

.decision-heading .MuiChip-label {
  min-width: 0;
  overflow: hidden;
  padding-right: 11px;
  padding-left: 11px;
  font-size: 0.64rem;
  font-weight: 900;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.decision-heading h1 {
  max-width: 100%;
  margin: 4px 0 0;
  color: var(--text-primary);
  font-size: clamp(1.9rem, 2.15vw, 2.35rem);
  line-height: 1;
  letter-spacing: 0;
  text-shadow: 0 16px 36px rgba(0, 0, 0, 0.42);
  text-wrap: balance;
}

.decision-kicker {
  color: rgba(238, 245, 255, 0.86);
  font-size: 0.74rem;
  font-weight: 900;
  letter-spacing: 0.04em;
}

.decision-context-grid {
  display: grid;
  grid-template-columns: minmax(150px, 0.62fr) minmax(220px, 1fr);
  gap: 7px;
  margin-top: 0;
}

.decision-context-card,
.decision-copy-card {
  min-width: 0;
  display: grid;
  align-content: center;
  gap: 5px;
  border: 1px solid rgba(102, 129, 162, 0.18);
  border-radius: 8px;
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.04), rgba(255, 255, 255, 0.012)),
    rgba(8, 16, 26, 0.52);
  box-shadow: inset 0 1px 0 rgba(210, 229, 255, 0.045);
}

.decision-context-card {
  min-height: 45px;
  padding: 7px 9px;
}

.decision-context-card span,
.decision-copy-card span {
  min-width: 0;
  overflow: hidden;
  color: rgba(175, 190, 210, 0.78);
  font-size: 0.58rem;
  font-weight: 900;
  line-height: 1.05;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.decision-context-card strong,
.decision-copy-card strong {
  min-width: 0;
  overflow: hidden;
  color: rgba(239, 244, 251, 0.9);
  font-size: 0.74rem;
  font-weight: 860;
  line-height: 1.22;
  overflow-wrap: anywhere;
  display: -webkit-box;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
}

.decision-context-card:first-child strong {
  color: var(--text-primary);
}

.decision-context-card.is-condition strong {
  color: rgba(233, 238, 247, 0.88);
  -webkit-line-clamp: 3;
}

.decision-protocol-panel {
  grid-area: protocol;
  align-content: start;
  position: relative;
  min-height: 86px;
  padding: 8px 14px 10px;
  overflow: hidden;
  background:
    radial-gradient(circle at 47% 52%, rgba(var(--yellow-rgb), 0.052), transparent 16%),
    radial-gradient(circle at 80% 48%, rgba(var(--green-rgb), 0.04), transparent 24%),
    linear-gradient(180deg, rgba(19, 36, 54, 0.58), rgba(6, 15, 26, 0.34)),
    rgba(4, 10, 17, 0.62);
}

.decision-protocol-panel::before {
  content: "";
  position: absolute;
  inset: 1px;
  pointer-events: none;
  border-radius: 8px;
  background:
    linear-gradient(90deg, rgba(var(--yellow-rgb), 0.1), transparent 14%, transparent 86%, rgba(var(--blue-rgb), 0.065));
  opacity: 0.34;
}

.decision-protocol-track {
  width: 100%;
  min-width: 0;
  position: relative;
  display: grid;
  grid-template-columns: repeat(7, minmax(0, 1fr));
  gap: 0;
  margin: 0;
  padding: 14px 8px 6px;
  list-style: none;
  border: 0;
  border-radius: 0;
  background: transparent;
  box-shadow: none;
  z-index: 1;
}

.decision-protocol-track::before {
  content: "";
  position: absolute;
  top: 21px;
  right: 14px;
  left: 14px;
  height: 1px;
  background:
    linear-gradient(90deg, rgba(var(--green-rgb), 0.5), rgba(var(--yellow-rgb), 0.68) 50%, rgba(var(--red-rgb), 0.5));
  box-shadow:
    0 0 10px rgba(var(--yellow-rgb), 0.12),
    0 0 18px rgba(var(--green-rgb), 0.06);
  opacity: 0.68;
  z-index: 0;
}

.decision-protocol-step {
  --protocol-rgb: 148, 160, 174;
  --protocol-color: var(--text-secondary);
  min-width: 0;
  position: relative;
  min-height: 46px;
  display: grid;
  align-content: start;
  justify-items: center;
  gap: 5px;
  padding: 0 6px;
  border: 1px solid transparent;
  border-radius: 0;
  color: rgba(204, 211, 220, 0.66);
  background: transparent;
  box-shadow: none;
  z-index: 1;
}

.decision-protocol-step + .decision-protocol-step::before {
  content: none;
}

.decision-protocol-step::after {
  content: "";
  order: -1;
  z-index: 1;
  width: 12px;
  height: 12px;
  border: 2px solid rgba(var(--protocol-rgb), 0.38);
  border-radius: 99px;
  background: rgba(7, 16, 27, 0.94);
  box-shadow:
    0 0 0 3px rgba(7, 16, 27, 0.86),
    0 0 12px rgba(var(--protocol-rgb), 0.08);
}

.decision-protocol-step span {
  position: relative;
  z-index: 2;
  min-width: 0;
  max-width: 100%;
  overflow: hidden;
  color: rgba(204, 214, 226, 0.72);
  font-size: 0.64rem;
  font-weight: 900;
  line-height: 1.14;
  text-align: center;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.decision-protocol-step.is-positive {
  --protocol-rgb: var(--green-rgb);
  --protocol-color: var(--green);
}

.decision-protocol-step.is-neutral {
  --protocol-rgb: 150, 160, 174;
  --protocol-color: rgba(200, 210, 224, 0.78);
}

.decision-protocol-step.is-caution {
  --protocol-rgb: var(--yellow-rgb);
  --protocol-color: var(--yellow);
}

.decision-protocol-step.is-negative {
  --protocol-rgb: var(--red-rgb);
  --protocol-color: #d96560;
}

.decision-protocol-step.is-active {
  color: var(--protocol-color);
}

.decision-protocol-step.is-active span {
  max-width: 142px;
  padding: 3px 10px;
  transform: translateY(-4px);
  border: 1px solid rgba(var(--protocol-rgb), 0.32);
  border-radius: 999px;
  color: var(--protocol-color);
  background:
    linear-gradient(180deg, rgba(var(--protocol-rgb), 0.14), rgba(var(--protocol-rgb), 0.045)),
    rgba(7, 16, 27, 0.7);
  box-shadow:
    inset 0 1px 0 rgba(255, 247, 190, 0.08),
    0 5px 14px rgba(var(--protocol-rgb), 0.08);
}

.decision-protocol-step.is-active::after {
  z-index: 2;
  transform: translateY(-1px);
  border-color: rgba(var(--protocol-rgb), 0.72);
  background: var(--protocol-color);
  width: 15px;
  height: 15px;
  box-shadow:
    0 0 0 5px rgba(var(--protocol-rgb), 0.07),
    0 0 0 10px rgba(var(--protocol-rgb), 0.02),
    0 0 15px rgba(var(--protocol-rgb), 0.16);
}

.decision-copy-panel {
  grid-area: copy;
  align-content: stretch;
  grid-template-rows: auto minmax(0, 1fr);
}

.decision-copy-stack {
  width: 100%;
  height: 100%;
  align-self: stretch;
  min-width: 0;
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  align-items: stretch;
  gap: 8px;
  padding-top: 0;
}

.decision-copy-card {
  height: 100%;
  min-height: 86px;
  align-content: center;
  gap: 7px;
  padding: 10px 12px;
}

.decision-copy-card strong {
  color: var(--text-primary);
  font-size: 0.7rem;
  -webkit-line-clamp: 3;
}

.decision-copy-card.is-note {
  border-color: rgba(var(--yellow-rgb), 0.2);
  background:
    linear-gradient(90deg, rgba(var(--yellow-rgb), 0.105), rgba(var(--yellow-rgb), 0.025)),
    rgba(0, 0, 0, 0.16);
  box-shadow:
    inset 2px 0 0 rgba(var(--yellow-rgb), 0.38),
    inset 0 1px 0 rgba(255, 255, 255, 0.045);
}

.decision-copy-card.is-note span {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  color: #e1cf83;
}

.decision-copy-card.is-note strong {
  color: #e8d889;
}

.decision-summary-panel.is-protocol-broken .decision-copy-card.is-note,
.decision-summary-panel.is-protocol-panic .decision-copy-card.is-note {
  color: #f0a3a3;
  background: rgba(var(--red-rgb), 0.09);
  border-color: rgba(var(--red-rgb), 0.22);
}

.decision-summary-panel.is-protocol-broken .decision-heading .MuiChip-root,
.decision-summary-panel.is-protocol-panic .decision-heading .MuiChip-root {
  max-width: 170px;
}

.decision-position-panel {
  grid-area: advice;
  align-content: stretch;
  grid-template-rows: auto auto minmax(0, 1fr);
}

.decision-position-note {
  min-width: 0;
  margin: -3px 0 0;
  overflow: hidden;
  color: var(--text-muted);
  font-size: 0.55rem;
  font-weight: 850;
  line-height: 1.25;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.decision-position-strip {
  width: 100%;
  height: 100%;
  align-self: stretch;
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  align-items: stretch;
  gap: 8px;
}

.decision-advice-pill,
.structure-split article,
.rail-risk-grid article,
.rail-scope-line,
.rail-internal-grid article,
.rail-trigger-list article,
.evidence-line,
.backtest-mini-stats article,
