}

.advice-policy-tooltip::-webkit-scrollbar-track {
  background: transparent;
}

.advice-policy-tooltip::-webkit-scrollbar-thumb {
  border-radius: 999px;
  background: rgba(244, 240, 231, 0.24);
}

.advice-policy-tooltip strong {
  min-width: 0;
  display: flex;
  align-items: center;
  justify-content: space-between;
