  color: #f4f0e7;
  font-size: 0.74rem;
  line-height: 1.2;
}

.advice-policy-tooltip strong span,
.advice-policy-tooltip strong b {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.advice-policy-tooltip strong b {
