  background: rgba(255, 255, 255, 0.045);
  text-align: center;
}

.advice-policy-meta span i,
.advice-policy-meta span b {
  min-width: 0;
  overflow: hidden;
  font-style: normal;
  line-height: 1.05;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.advice-policy-meta span i {
  color: rgba(244, 240, 231, 0.58);
  font-size: 0.52rem;
  font-weight: 820;
}

.advice-policy-meta span b {
  color: rgba(244, 240, 231, 0.9);
  font-size: 0.62rem;
  font-weight: 950;
}

.advice-policy-tooltip p {
  min-width: 0;
  display: -webkit-box;
  overflow: hidden;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
  margin: 0;
  color: rgba(244, 240, 231, 0.78);
  font-size: 0.63rem;
