  background: rgba(255, 255, 255, 0.048);
  font-weight: 860;
}

.advice-policy-tooltip ul {
  display: grid;
  gap: 4px;
  max-height: 130px;
  overflow-y: auto;
  overscroll-behavior: contain;
  margin: 0;
  padding: 0 2px 0 0;
  list-style: none;
  scrollbar-width: thin;
  scrollbar-color: rgba(244, 240, 231, 0.2) transparent;
}

.advice-policy-tooltip ul::-webkit-scrollbar {
  width: 3px;
}

.advice-policy-tooltip ul::-webkit-scrollbar-track {
  background: transparent;
}

.advice-policy-tooltip ul::-webkit-scrollbar-thumb {
