  padding: 3px;
  border: 1px solid var(--line-soft);
  border-radius: 10px;
  color: var(--text-secondary);
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.052), rgba(255, 255, 255, 0.012)),
    var(--surface-quiet);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.06);
  cursor: pointer;
}

.appearance-mode-switch span {
  position: relative;
  z-index: 1;
  min-width: 0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  height: 34px;
  border-radius: 8px;
  font-size: 0.72rem;
  font-weight: 900;
  transition:
    color 160ms ease,
    transform 160ms ease;
}

.appearance-mode-switch .MuiSvgIcon-root {
  font-size: 1rem;
}

.appearance-mode-switch i {
  position: absolute;
  top: 3px;
  bottom: 3px;
  left: 3px;
  width: calc(50% - 3px);
  border-radius: 8px;
  background:
    linear-gradient(180deg, rgba(var(--yellow-rgb), 0.18), rgba(var(--yellow-rgb), 0.06)),
    rgba(255, 255, 255, 0.055);
  border: 1px solid rgba(var(--yellow-rgb), 0.18);
  box-shadow:
    0 10px 20px rgba(0, 0, 0, 0.16),
    inset 0 1px 0 rgba(255, 255, 255, 0.12);
  transition:
    transform 180ms ease,
    background-color 180ms ease,
    border-color 180ms ease;
}

.appearance-mode-switch[aria-checked="false"] .is-dark,
.appearance-mode-switch[aria-checked="true"] .is-light {
  color: var(--text-primary);
}

.appearance-mode-switch[aria-checked="true"] i {
  transform: translateX(100%);
}

.appearance-mode-switch:hover {
  border-color: var(--line-visible);
}

.appearance-mode-switch:focus-visible {
  outline: 0;
  box-shadow:
    0 0 0 2px rgba(var(--yellow-rgb), 0.18),
    inset 0 1px 0 rgba(255, 255, 255, 0.06);
}

