.asset-panel {
  position: relative;
  min-height: auto;
  padding: 5px 2px 2px 6px;
  overflow: hidden;
  background: transparent;
  border-color: transparent;
  box-shadow: none;
  backdrop-filter: none;
  -webkit-backdrop-filter: none;
}

.asset-panel::before,
.asset-panel::after,
.strength-scroll-wrap::before,
.strength-scroll-wrap::after {
  content: "";
  position: absolute;
  top: 0;
  bottom: 0;
  z-index: 2;
  width: 14px;
  pointer-events: none;
  opacity: 0.38;
  backdrop-filter: blur(2px);
  -webkit-backdrop-filter: blur(2px);
}

.asset-panel::before,
.strength-scroll-wrap::before {
  left: 0;
  background: linear-gradient(90deg, rgba(18, 21, 26, 0.18), rgba(18, 21, 26, 0));
}

.asset-panel::after,
.strength-scroll-wrap::after {
  right: 0;
  background: linear-gradient(270deg, rgba(18, 21, 26, 0.18), rgba(18, 21, 26, 0));
}

.asset-panel::before,
.asset-panel::after {
  display: none;
}

.asset-list {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(136px, 1fr));
  gap: 8px;
  overflow: visible;
  padding: 0;
  margin-inline: 0;
  scrollbar-width: none;
  scrollbar-gutter: auto;
}

.asset-list::-webkit-scrollbar {
  display: none;
}

.drag-scroll {
  cursor: grab;
  -webkit-user-select: none;
  user-select: none;
}

.drag-scroll.is-dragging {
  cursor: grabbing;
  scroll-behavior: auto;
}

.asset-item {
  position: relative;
  min-width: 0;
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  align-items: center;
  gap: 7px;
  min-height: 76px;
  padding: 9px 10px 7px;
  border-radius: 9px;
  overflow: hidden;
  background:
    linear-gradient(145deg, rgba(132, 167, 207, 0.08), rgba(132, 167, 207, 0.018)),
    rgba(8, 16, 26, 0.72);
  border: 1px solid rgba(118, 154, 190, 0.105);
  box-shadow:
    inset 0 1px 0 rgba(196, 220, 255, 0.055),
    0 12px 28px rgba(0, 0, 0, 0.2);
}

.asset-light {
  grid-row: span 2;
  width: 6px;
  height: 46px;
  border-radius: 99px;
  background: var(--green);
  box-shadow: 0 0 14px rgba(101, 201, 143, 0.2);
}

.asset-item.is-yellow .asset-light {
  background: var(--yellow);
  box-shadow: 0 0 14px rgba(216, 194, 107, 0.2);
}

.asset-item.is-red .asset-light {
  background: var(--red);
  box-shadow: 0 0 14px rgba(231, 111, 115, 0.2);
}

.asset-main,
.asset-meta {
  min-width: 0;
}

.asset-main strong {
  display: block;
  overflow: hidden;
  color: var(--text-primary);
  font-size: 0.72rem;
  line-height: 1;
  text-overflow: ellipsis;
}

.asset-main small {
  display: block;
  max-width: 100%;
  margin-top: 4px;
  overflow: hidden;
  color: var(--text-muted);
  font-size: 0.56rem;
  font-weight: 850;
  line-height: 1;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.asset-meta {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  justify-content: center;
  gap: 5px;
  grid-column: 2;
  padding-right: 52px;
}

.asset-meta span {
  max-width: 100%;
  overflow: hidden;
  color: var(--text-primary);
  font-size: 0.88rem;
  font-weight: 800;
  text-overflow: ellipsis;
}

.asset-meta em {
  display: inline-flex;
  align-items: center;
  gap: 2px;
  max-width: 100%;
  overflow: hidden;
  color: var(--text-muted);
  font-size: 0.68rem;
  font-style: normal;
  font-weight: 800;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.asset-meta em.is-positive {
  color: var(--red);
}

.asset-meta em.is-negative {
  color: var(--green);
}

.asset-meta em.is-flat {
  color: var(--yellow);
}

.asset-sparkline {
  position: absolute;
  right: 8px;
  bottom: 8px;
  width: 48px;
  height: 21px;
  opacity: 0.92;
}

.asset-sparkline polyline {
  fill: none;
  stroke: var(--red);
  stroke-width: 2;
  stroke-linecap: round;
  stroke-linejoin: round;
  filter: drop-shadow(0 0 5px rgba(var(--red-rgb), 0.18));
}

.asset-sparkline.is-negative polyline {
  stroke: var(--green);
  filter: drop-shadow(0 0 5px rgba(var(--green-rgb), 0.16));
}

