  color: var(--position-color);
  font-size: 1rem;
}

.position-target {
  flex: 0 0 auto;
  color: var(--position-color);
  font-size: 0.84rem;
  line-height: 1.1;
}

.position-detail p {
  min-width: 0;
  margin: 0;
  display: -webkit-box;
  overflow: hidden;
  color: var(--text-secondary);
  font-size: 0.68rem;
  line-height: 1.32;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
}

.position-detail em {
  flex: 0 0 auto;
  color: var(--text-primary);
  font-size: 0.68rem;
  font-style: normal;
  font-weight: 900;
  white-space: nowrap;
}

.position-triggers {
  display: grid;
  gap: 3px;
}

.position-triggers span {
  display: -webkit-box;
  overflow: hidden;
  color: var(--text-muted);
  font-size: 0.64rem;
  line-height: 1.25;
  -webkit-line-clamp: 1;
  -webkit-box-orient: vertical;
}

.reason-list {
  display: grid;
  gap: 7px;
}

.reason-item {
  display: grid;
  grid-template-columns: 34px minmax(0, 1fr);
  gap: 8px;
  padding: 8px;
  border-radius: 10px;
  background: rgba(255, 255, 255, 0.035);
  border: 1px solid rgba(255, 255, 255, 0.06);
}

.reason-item strong {
  color: var(--red);
  font-size: 0.82rem;
}

.reason-item p {
  margin: 0;
  color: var(--text-primary);
  font-size: 0.76rem;
  line-height: 1.38;
}

.evidence-block {
  display: grid;
  gap: 6px;
  margin-top: 10px;
}

.evidence-block > span {
  color: var(--text-muted);
  font-size: 0.64rem;
  font-weight: 900;
}

.support-item {
  min-width: 0;
  padding: 7px 8px;
  border-radius: 9px;
  background: rgba(var(--green-rgb), 0.045);
  border: 1px solid rgba(var(--green-rgb), 0.1);
}

.support-item strong {
  display: block;
  color: var(--green);
  font-size: 0.68rem;
}

.support-item p {
  margin: 3px 0 0;
  color: var(--text-secondary);
  font-size: 0.66rem;
  line-height: 1.28;
}

.policy-note {
  margin-top: 9px;
}

.error-card {
  flex: 0 0 auto;
  border-color: rgba(231, 111, 115, 0.22) !important;
  background: rgba(97, 42, 47, 0.42) !important;
}

.error-card .MuiCardContent-root {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 12px !important;
  color: #f2b2b4;
}

.loading-state {
  flex: 1 1 0;
  min-height: 0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  min-height: 220px;
  color: var(--text-secondary);
  font-size: 0.9rem;
  border: 1px solid rgba(255, 255, 255, 0.06);
  border-radius: 12px;
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.035), rgba(255, 255, 255, 0.012)),
    rgba(18, 21, 26, 0.64);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
}

.analysis-empty-state {
  flex: 1 1 0;
  min-height: 220px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
  padding: 24px;
  color: var(--text-secondary);
  border: 1px solid rgba(255, 255, 255, 0.06);
  border-radius: 12px;
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.035), rgba(255, 255, 255, 0.012)),
    rgba(18, 21, 26, 0.64);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
}

.analysis-empty-state > .MuiSvgIcon-root {
  flex: 0 0 auto;
  color: var(--green);
  font-size: 1.25rem;
}

.analysis-empty-state > div {
  min-width: 0;
  display: grid;
  gap: 3px;
}

.analysis-empty-state strong {
  color: var(--text-primary);
  font-size: 0.92rem;
  font-weight: 900;
}

.analysis-empty-state span {
  color: var(--text-muted);
  font-size: 0.76rem;
  font-weight: 760;
}

