.workspace-shell {
  --workspace-menu-width: 154px;
  flex: 1 1 0;
  min-width: 0;
  min-height: 0;
  display: grid;
  grid-template-columns: var(--workspace-menu-width) minmax(0, 1fr);
  gap: 12px;
  overflow: visible;
  transition: grid-template-columns 180ms ease;
}

.workspace-shell.is-sidebar-collapsed {
  --workspace-menu-width: 58px;
}

.app-menu {
  position: relative;
  z-index: 31;
  min-width: 0;
  min-height: 0;
  align-self: stretch;
  display: grid;
  align-content: start;
  gap: 8px;
  height: 100dvh;
  margin: calc(-1 * (var(--window-drag-height) + 12px)) 0 -12px -16px;
  padding: calc(var(--window-drag-height) + 18px) 14px 12px;
  overflow: auto;
  overscroll-behavior: contain;
  border: 0;
  border-right: 1px solid var(--line-soft);
  border-radius: 0;
  background:
    linear-gradient(180deg, rgba(127, 159, 194, 0.036), rgba(20, 160, 111, 0.01)),
    var(--window-chrome-bg);
  box-shadow: inset -1px 0 0 rgba(196, 220, 255, 0.026);
  scrollbar-color: rgba(107, 128, 150, 0.22) rgba(4, 9, 15, 0.16);
  scrollbar-width: thin;
}

.app-menu::-webkit-scrollbar,
.workspace-area::-webkit-scrollbar,
.holdings-table-wrap::-webkit-scrollbar {
  width: 4px;
  height: 4px;
}

.app-menu::-webkit-scrollbar-track,
.workspace-area::-webkit-scrollbar-track,
.holdings-table-wrap::-webkit-scrollbar-track {
  background: rgba(5, 11, 18, 0.18);
  border-radius: 999px;
}

.app-menu::-webkit-scrollbar-thumb,
.workspace-area::-webkit-scrollbar-thumb,
.holdings-table-wrap::-webkit-scrollbar-thumb {
  background: rgba(103, 128, 154, 0.24);
  border: 0;
  border-radius: 999px;
}

.app-menu > button {
  position: relative;
  min-width: 0;
  min-height: 46px;
  display: grid;
  grid-template-columns: 28px minmax(0, 1fr);
  align-items: center;
  gap: 10px;
  padding: 10px 12px;
  border: 1px solid transparent;
  border-radius: 9px;
  color: var(--text-secondary);
  background: transparent;
  font: inherit;
  text-align: left;
  cursor: pointer;
  touch-action: manipulation;
  transition:
    border-color 160ms ease,
    background-color 160ms ease,
    color 160ms ease,
    transform 160ms ease;
}

.app-menu > button:hover {
  color: var(--text-primary);
  border-color: rgba(116, 145, 176, 0.1);
  background:
    linear-gradient(90deg, rgba(127, 159, 194, 0.07), rgba(127, 159, 194, 0.016)),
    rgba(255, 255, 255, 0.018);
}

.app-menu > button:focus-visible {
  outline: 0;
  box-shadow: 0 0 0 2px rgba(var(--green-rgb), 0.24);
}

.app-menu > button.is-active {
  color: var(--text-primary);
  border-color: rgba(var(--green-rgb), 0.18);
  background:
    linear-gradient(90deg, rgba(var(--green-rgb), 0.12), rgba(127, 159, 194, 0.026)),
    rgba(255, 255, 255, 0.022);
}

.app-menu > button.is-active::before {
  content: "";
  position: absolute;
  inset: 9px auto 9px 3px;
  width: 2px;
  border-radius: 999px;
  background: var(--green);
}

.app-menu > button .MuiSvgIcon-root {
  justify-self: center;
  font-size: 1.06rem;
}

.app-menu > button span {
  min-width: 0;
  display: grid;
  gap: 1px;
}

.app-menu > button strong {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.app-menu > button strong {
  font-size: 0.86rem;
  font-weight: 920;
  line-height: 1.15;
}

.workspace-shell.is-sidebar-collapsed .app-menu {
  gap: 6px;
  padding: calc(var(--window-drag-height) + 18px) 9px 12px;
}

.workspace-shell.is-sidebar-collapsed .app-menu > button {
  min-height: 36px;
  grid-template-columns: minmax(0, 1fr);
  justify-items: center;
  gap: 0;
  padding: 0;
}

.workspace-shell.is-sidebar-collapsed .app-menu > button::before {
  inset: 9px auto 9px 3px;
  width: 2px;
  height: auto;
}

.workspace-shell.is-sidebar-collapsed .app-menu > button span {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  clip-path: inset(50%);
  white-space: nowrap;
}

