:root {
  --workspace-side-rail-width: clamp(300px, 22vw, 360px);
}

.analysis-page-stack.has-decision-rail,
.holdings-workspace.has-record-rail {
  grid-template-columns: minmax(0, 1fr) var(--workspace-side-rail-width);
  gap: 0;
}

.analysis-page-stack.has-decision-rail .analysis-main-column,
.holdings-workspace.has-record-rail .holdings-main-column {
  padding-right: 10px;
}

.decision-rail,
.holdings-record-rail {
  position: relative;
  z-index: 31;
  isolation: isolate;
  min-width: 0;
  min-height: 0;
  align-self: stretch;
  width: 100%;
  border-left: 0;
  background: transparent;
  box-shadow: none;
  backdrop-filter: none;
  -webkit-backdrop-filter: none;
}

.decision-rail::before,
.holdings-record-rail::before {
  content: "";
  position: fixed;
  z-index: 0;
  inset: 0 0 0 auto;
  width: calc(var(--workspace-side-rail-width) + 4px);
  pointer-events: none;
  border-left: 1px solid var(--line-soft);
  background:
    linear-gradient(180deg, rgba(127, 159, 194, 0.036), rgba(20, 160, 111, 0.01)),
    var(--window-chrome-bg);
  box-shadow: inset 1px 0 0 rgba(196, 220, 255, 0.026);
}

.decision-rail > *,
.holdings-record-rail > * {
  position: relative;
  z-index: 1;
}

