.decision-rail .rail-risk-grid article,
.decision-rail .rail-internal-grid article,
.decision-rail .rail-scope-line,
.decision-rail .rail-trigger-list article,
.decision-rail .rail-position-list article {
  border-radius: 8px;
}

.decision-main-scroll {
  gap: 10px;
  padding-right: 2px;
  padding-bottom: 16px;
}

.holdings-record-rail .trade-habit-board {
  grid-template-rows: auto minmax(0, 1fr);
}

.holdings-record-rail .trade-habit-head {
  min-height: 32px;
  padding-bottom: 7px;
}

.trade-record-panel {
  grid-template-rows: auto auto minmax(0, 1fr);
  gap: 10px;
}

.trade-overview-card {
  gap: 10px;
  padding: 11px;
}

.trade-stat-grid {
  gap: 6px;
}

.trade-stat-grid article {
  padding: 7px;
}

.trade-signal-board {
