html[data-rportfolio-style="light"] .decision-rail::-webkit-scrollbar-thumb,
html[data-rportfolio-style="light"] .holdings-record-rail .trade-ledger-stack::-webkit-scrollbar-thumb,
html[data-rportfolio-style="light"] .trade-list-mini::-webkit-scrollbar-thumb,
html[data-rportfolio-style="light"] .holdings-table-wrap::-webkit-scrollbar-thumb {
