}

@media (prefers-reduced-motion: reduce) {
  .rail-collapse-titlebar-button,
  .rail-collapse-icon,
  .workspace-shell,
  .app-menu > button,
  .icon-text-button,
  .primary-action-button,
  .holdings-table button {
    transition: none;
  }

  .icon-text-button:hover,
  .primary-action-button:hover,
  .holdings-table button:hover {
    transform: none;
  }
}

@media (max-width: 1180px) {
  .workspace-shell {
    min-height: auto;
    grid-template-columns: minmax(0, 1fr);
    overflow: visible;
  }

  .workspace-shell.is-sidebar-collapsed {
    --workspace-menu-width: auto;
    grid-template-columns: minmax(0, 1fr);
  }

  .app-menu {
    grid-auto-flow: column;
    grid-auto-columns: minmax(156px, 1fr);
    height: auto;
    margin: 0;
    padding: 6px 8px;
    overflow-x: auto;
  }

  .workspace-shell.is-sidebar-collapsed .app-menu > button {
    min-height: 54px;
    grid-template-columns: 28px minmax(0, 1fr);
    justify-items: stretch;
    gap: 8px;
    padding: 9px;
  }

  .workspace-shell.is-sidebar-collapsed .app-menu > button::before {
    inset: 10px auto 10px 6px;
    width: 2px;
    height: auto;
  }

  .workspace-shell.is-sidebar-collapsed .app-menu > button span {
    position: static;
    width: auto;
    height: auto;
    overflow: hidden;
    clip: auto;
    clip-path: none;
    white-space: normal;
  }

  .workspace-area,
  .analysis-page-stack,
  .holdings-workspace {
    overflow: visible;
  }

  .holdings-grid {
    grid-template-columns: minmax(0, 1fr);
  }

  .trade-habit-grid {
    grid-template-columns: minmax(0, 1fr);
  }
}

@media (max-width: 820px) {
  .holdings-page-head,
  .holding-form-footer,
  .holding-form-tools {
    grid-template-columns: minmax(0, 1fr);
  }

  .holdings-head-actions {
    justify-items: start;
  }

  .holding-card-head,
  .holding-list-actions {
    display: grid;
    grid-template-columns: minmax(0, 1fr);
    justify-items: start;
  }

  .holding-list-actions {
    min-width: 0;
    width: 100%;
    grid-template-columns: minmax(0, 1fr) auto auto;
    align-items: center;
    justify-items: stretch;
  }

  .holding-list-actions p,
  .holding-form-tools p {
    width: 100%;
    text-align: left;
    white-space: normal;
  }

  .holdings-summary-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .trade-habit-summary {
    display: grid;
  }

  .trade-habit-summary span {
    white-space: normal;
  }

  .trade-habit-actions {
    grid-template-columns: minmax(0, 1fr);
  }

  .position-policy-grid {
    grid-template-columns: minmax(0, 1fr);
  }

  .holding-role-segment,
  .holding-form-grid {
    grid-template-columns: minmax(0, 1fr);
  }

  .primary-action-button {
    width: 100%;
  }

  .holding-form-layer {
    align-items: end;
    padding: calc(var(--window-drag-height) + 10px) 10px 10px;
  }

  .holding-form-dialog {
    width: 100%;
    max-height: calc(100dvh - var(--window-drag-height) - 20px);
  }
}

@media (max-width: 560px) {
  .workspace-shell {
    gap: 8px;
  }

  .app-menu {
    padding: 6px;
  }

  .app-menu > button {
    min-height: 54px;
  }

  .holdings-summary-grid {
    grid-template-columns: minmax(0, 1fr);
  }

  .holdings-page-head,
  .holding-form-card,
  .holdings-list-card {
    padding: 12px;
  }
}

/* rMarket holdings workspace: dense ledger-style polish. */
.holdings-workspace {
  --holdings-line: rgba(127, 159, 194, 0.13);
  --holdings-line-strong: rgba(127, 159, 194, 0.2);
  --holdings-paper: rgba(6, 12, 20, 0.7);
  --holdings-paper-soft: rgba(127, 159, 194, 0.055);
  --holdings-hover: rgba(127, 159, 194, 0.075);
  --holdings-ink-soft: rgba(186, 197, 209, 0.74);
  --holding-tone-rgb: var(--green-rgb);
  gap: 12px;
  padding: 0 2px 10px 0;
  font-family: "Avenir Next", "PingFang SC", "Hiragino Sans GB", sans-serif;
}

.holdings-main-column {
  gap: 12px;
}

.holdings-page-head {
  min-height: 44px;
  padding: 9px 12px;
  border-color: var(--holdings-line);
  border-radius: 8px;
  background:
    linear-gradient(90deg, rgba(var(--green-rgb), 0.09), rgba(var(--blue-rgb), 0.034) 52%, rgba(var(--yellow-rgb), 0.028)),
    rgba(6, 12, 20, 0.66);
  box-shadow: inset 0 1px 0 rgba(196, 220, 255, 0.055);
}

.holdings-page-head h1 {
  font-size: 1.06rem;
  font-weight: 900;
}

.holdings-head-actions span,
.holdings-head-actions strong {
  height: 26px;
  border-radius: 7px;
}

.holdings-summary-grid {
  gap: 7px;
}

.holdings-summary-card {
  min-height: 86px;
  gap: 8px;
  padding: 10px 11px;
  border-color: var(--holdings-line);
  border-radius: 8px;
  background:
    linear-gradient(180deg, rgba(196, 220, 255, 0.035), rgba(196, 220, 255, 0.006)),
    rgba(6, 12, 20, 0.58);
  box-shadow: inset 0 1px 0 rgba(196, 220, 255, 0.05);
}

.holdings-summary-card span {
  font-size: 0.64rem;
  letter-spacing: 0;
}

.holdings-summary-card strong,
.holding-detail-metrics strong,
.holding-band-meter-head strong,
.holding-detail-callout strong,
.holdings-asset-table td > strong {
