  letter-spacing: 0;
}

.position-map-panel {
  gap: 9px;
  padding: 11px 12px;
  border-color: var(--holdings-line);
  border-radius: 8px;
  background:
    linear-gradient(90deg, rgba(var(--green-rgb), 0.07), rgba(var(--blue-rgb), 0.03) 54%, rgba(var(--yellow-rgb), 0.025)),
    rgba(6, 12, 20, 0.58);
