  box-shadow: none;
}

.holding-card-head {
  min-height: 34px;
  padding: 0 2px;
}

.holding-card-head span {
  font-size: 0.58rem;
  letter-spacing: 0;
}

.holding-list-actions {
  gap: 7px;
}

.holding-list-actions p {
