}

.holding-detail-metrics {
  gap: 6px;
}

.holding-detail-metrics article,
.holding-horizon-grid article {
  border-color: rgba(127, 159, 194, 0.09);
  border-radius: 8px;
  background: rgba(127, 159, 194, 0.035);
}

.holding-detail-metrics article {
  min-height: 62px;
  padding: 9px;
}

.holding-detail-metrics span,
.holding-horizon-grid span,
.holding-band-meter-head span {
  color: rgba(122, 135, 150, 0.88);
  font-size: 0.58rem;
  letter-spacing: 0;
}

.holding-detail-metrics strong {
  font-size: 0.95rem;
}

.holding-band-meter {
  min-width: 0;
  display: grid;
  gap: 7px;
  padding: 9px 10px;
  border: 1px solid rgba(var(--holding-tone-rgb), 0.16);
  border-radius: 8px;
  background:
    linear-gradient(90deg, rgba(var(--holding-tone-rgb), 0.08), rgba(127, 159, 194, 0.025)),
