  justify-content: space-between;
  gap: 8px;
}

.holding-band-meter-head strong {
  color: var(--text-primary);
  font-size: 0.76rem;
  font-weight: 950;
}

.holding-band-track {
  position: relative;
  height: 20px;
  overflow: hidden;
  border: 1px solid rgba(127, 159, 194, 0.09);
  border-radius: 999px;
  background:
    linear-gradient(90deg, rgba(127, 159, 194, 0.12), rgba(127, 159, 194, 0.035)),
    rgba(2, 7, 12, 0.42);
}

.holding-band-range,
.holding-band-target,
.holding-band-current {
  position: absolute;
  top: 50%;
  display: block;
  transform: translateY(-50%);
}

.holding-band-range {
  left: var(--band-min);
  width: var(--band-width);
  height: 9px;
  border-radius: 999px;
  background: rgba(var(--holding-tone-rgb), 0.42);
  box-shadow: 0 0 0 1px rgba(var(--holding-tone-rgb), 0.16);
}

.holding-band-target {
  left: var(--band-target);
  width: 2px;
  height: 15px;
  border-radius: 999px;
  background: rgba(243, 247, 251, 0.7);
}

.holding-band-current {
  left: var(--band-current);
  width: 9px;
  height: 18px;
  border: 2px solid rgba(4, 9, 15, 0.95);
  border-radius: 999px;
  background: rgb(var(--holding-tone-rgb));
  box-shadow: 0 0 0 1px rgba(243, 247, 251, 0.22);
}

