}

.holding-band-scale {
  color: rgba(122, 135, 150, 0.82);
  font-size: 0.58rem;
  font-weight: 820;
}

.holding-detail-callout {
  gap: 5px;
  padding: 10px 11px;
  border-color: rgba(var(--holding-tone-rgb), 0.17);
  border-left-width: 3px;
  border-radius: 8px;
  background:
    linear-gradient(90deg, rgba(var(--holding-tone-rgb), 0.13), rgba(127, 159, 194, 0.028)),
