    rgba(4, 9, 15, 0.3);
}

.holding-detail-callout span {
  color: rgba(var(--holding-tone-rgb), 0.96);
  font-size: 0.62rem;
}

.holding-detail-callout strong {
  font-size: 1.06rem;
}

.holding-detail-callout p {
  display: -webkit-box;
  overflow: hidden;
  color: rgba(218, 226, 236, 0.78);
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
}

.holding-horizon-grid {
  grid-template-columns: minmax(0, 1fr);
  gap: 6px;
}

.holding-horizon-grid article {
  min-height: 52px;
  grid-template-columns: 48px minmax(0, 1fr);
  grid-template-rows: auto auto;
  align-items: center;
  column-gap: 8px;
  padding: 8px 9px;
}

.holding-horizon-grid span {
  grid-row: 1 / 3;
  align-self: stretch;
  display: grid;
  place-items: center;
  border-right: 1px solid rgba(127, 159, 194, 0.09);
}

.holding-horizon-grid strong,
.holding-horizon-grid em {
  grid-column: 2;
}

.holding-horizon-grid em {
  white-space: nowrap;
}

.holding-detail-foot {
  gap: 5px;
  padding-top: 9px;
  border-top-color: rgba(127, 159, 194, 0.1);
}

.holding-detail-foot strong {
  white-space: normal;
}

.trade-overview-card,
