@media (max-width: 1280px) {
  .holdings-asset-workbench {
    grid-template-columns: minmax(420px, 1fr) minmax(300px, 340px);
  }
}

@media (max-width: 1040px) {
  .holdings-workspace.has-record-rail {
    grid-template-columns: minmax(0, 1fr);
  }

  .holdings-workspace.has-record-rail .holdings-main-column {
    padding-right: 0;
  }

  .holdings-record-rail {
    display: none;
  }

  .holdings-asset-workbench {
    grid-template-columns: minmax(0, 1fr);
  }

  .holdings-asset-workbench .holdings-table-wrap,
  .holding-detail-panel {
    min-height: 0;
  }

  .holding-horizon-grid {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }

  .holding-horizon-grid article {
    grid-template-columns: minmax(0, 1fr);
    grid-template-rows: auto auto auto;
  }

  .holding-horizon-grid span,
  .holding-horizon-grid strong,
  .holding-horizon-grid em {
    grid-column: auto;
  }

  .holding-horizon-grid span {
    grid-row: auto;
    justify-content: start;
    place-items: start;
    border-right: 0;
  }
}

@media (max-width: 760px) {
  .holdings-page-head,
  .holding-card-head,
  .holding-list-actions {
    grid-template-columns: minmax(0, 1fr);
    align-items: start;
  }

  .holding-list-actions {
    width: 100%;
    display: grid;
    grid-template-columns: minmax(0, 1fr) auto auto;
  }

  .holdings-summary-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .position-chart-grid,
  .position-donut-layout,
  .position-band-layout {
    grid-template-columns: minmax(0, 1fr);
  }

  .position-chart-cell.is-band {
    padding-left: 0;
    border-left: 0;
  }

  .holdings-table.holdings-asset-table {
    min-width: 620px;
  }

  .holding-horizon-grid {
    grid-template-columns: minmax(0, 1fr);
  }
}

@media (max-width: 560px) {
  .holdings-page-head,
  .holding-form-card {
    padding: 10px;
  }

  .holdings-list-card {
    padding: 0;
  }

  .holdings-summary-grid {
    grid-template-columns: minmax(0, 1fr);
  }

  .holding-list-actions {
    grid-template-columns: minmax(0, 1fr);
  }

  .holding-list-actions .icon-text-button {
    width: 100%;
  }
}

.holdings-table.holdings-asset-table {
  min-width: 0;
}

.holdings-asset-table th:nth-child(2),
.holdings-asset-table td.holding-value-cell {
  width: 148px;
}

.holdings-asset-table th:nth-child(3),
.holdings-asset-table td.holding-weight-cell {
  width: 104px;
}

.holdings-asset-table th:nth-child(4),
.holdings-asset-table td.holding-advice-cell {
  width: 116px;
}

.holding-detail-callout {
  min-height: 72px;
}

html[data-rportfolio-style="light"] .holding-detail-panel.is-caution .holding-detail-callout,
html[data-rportfolio-style="light"] .holding-detail-panel.is-negative .holding-detail-callout {
