}

@media (max-width: 1180px) {
  .workspace-shell,
  .workspace-shell.is-sidebar-collapsed {
    display: flex;
    flex-direction: column;
    gap: 10px;
    min-height: 0;
    overflow: visible;
  }

  .app-menu,
  .workspace-shell.is-sidebar-collapsed .app-menu {
    width: 100%;
    height: auto;
    min-height: 0;
    align-self: auto;
    grid-auto-flow: column;
    grid-auto-columns: minmax(150px, 1fr);
    margin: 0;
    padding: 6px;
    overflow-x: auto;
    overflow-y: hidden;
    border-right: 0;
    border-bottom: 1px solid var(--line-soft);
    border-radius: 0;
  }

  .workspace-shell.is-sidebar-collapsed .app-menu > button,
  .app-menu > button {
    min-height: 46px;
    grid-template-columns: 28px minmax(0, 1fr);
    justify-items: stretch;
    gap: 8px;
    padding: 9px 10px;
  }

  .workspace-shell.is-sidebar-collapsed .app-menu > button span {
    position: static;
    width: auto;
    height: auto;
    overflow: hidden;
    clip: auto;
    clip-path: none;
    white-space: normal;
  }

  .workspace-area {
    flex: 1 1 auto;
    min-height: 0;
  }
}

@media (max-width: 760px) {
  .holdings-table.holdings-asset-table {
    min-width: 620px;
  }
}

@media (min-width: 761px) {
  .holding-horizon-grid {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }

  .holding-horizon-grid article {
    min-height: 72px;
    grid-template-columns: minmax(0, 1fr);
    grid-template-rows: auto auto minmax(0, 1fr);
    align-items: start;
    gap: 4px;
    padding: 8px;
  }

  .holding-horizon-grid span,
  .holding-horizon-grid strong,
  .holding-horizon-grid em {
    grid-column: 1;
    grid-row: auto;
  }

  .holding-horizon-grid span {
    display: block;
    border-right: 0;
  }

  .holding-horizon-grid strong {
    white-space: normal;
    line-height: 1.12;
  }

  .holding-horizon-grid em {
    display: -webkit-box;
    overflow: hidden;
    white-space: normal;
    -webkit-box-orient: vertical;
    -webkit-line-clamp: 2;
  }
}

