/* Decision intelligence v1: confidence, damage and risk-vector presentation. */
.decision-heading {
  align-content: start;
  gap: 6px;
  grid-template-rows: auto auto auto;
  padding: 9px 10px;
}

.decision-title-row {
  align-items: center;
  min-height: 32px;
  gap: 8px;
}

.decision-title-row > div {
  display: flex;
  min-width: 0;
  align-items: center;
}

.decision-heading h1 {
  margin: 0;
  font-size: clamp(1.48rem, 1.8vw, 2rem);
  line-height: 1.02;
}

.decision-heading .MuiChip-root {
  height: 26px;
  max-width: min(100%, 178px);
  margin-top: 0;
}

.decision-heading .MuiChip-label {
  padding-right: 10px;
  padding-left: 10px;
  font-size: 0.6rem;
}

.decision-context-grid {
  grid-template-columns: minmax(150px, 0.62fr) minmax(220px, 1fr);
  gap: 6px;
}

.decision-context-card {
  min-height: 39px;
  gap: 3px;
  padding: 6px 8px;
}

.decision-context-card span {
  font-size: 0.55rem;
}

.decision-context-card strong {
  font-size: 0.7rem;
  line-height: 1.15;
}

.decision-context-card.is-condition strong {
  -webkit-line-clamp: 2;
}

.decision-intelligence-strip {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 7px;
  min-height: 52px;
  margin-top: 2px;
}

.decision-intelligence-chip {
  min-width: 0;
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  grid-template-rows: auto auto auto;
  align-content: center;
  justify-items: start;
  gap: 2px;
  min-height: 52px;
  padding: 7px 10px;
  overflow: hidden;
  border: 1px solid rgba(102, 129, 162, 0.14);
  border-radius: 10px;
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.035), rgba(255, 255, 255, 0.01)),
    rgba(8, 16, 26, 0.38);
  box-shadow: inset 0 1px 0 rgba(210, 229, 255, 0.04);
}

.decision-intelligence-chip span,
.decision-intelligence-chip em {
  min-width: 0;
  overflow: hidden;
  color: rgba(175, 190, 210, 0.78);
  font-size: 0.62rem;
  font-style: normal;
  font-weight: 860;
  line-height: 1.15;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.decision-intelligence-chip strong {
  min-width: 0;
  overflow: hidden;
  color: rgba(239, 244, 251, 0.9);
  font-size: 0.76rem;
  font-weight: 900;
  line-height: 1.15;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.decision-intelligence-chip em {
  justify-self: start;
  font-size: 0.6rem;
}

.decision-intelligence-chip strong {
  justify-self: start;
}

.decision-intelligence-chip.is-signal {
  grid-column: auto;
}

.decision-intelligence-chip.is-positive strong,
.decision-intelligence-chip.is-positive em {
  color: var(--green);
}

.decision-intelligence-chip.is-caution strong,
.decision-intelligence-chip.is-caution em {
  color: var(--yellow);
}

.decision-intelligence-chip.is-negative strong,
.decision-intelligence-chip.is-negative em {
  color: var(--red);
}

.decision-position-panel {
  align-self: start;
  align-content: start;
  grid-template-rows: auto auto;
}

.decision-context-card.is-positive strong {
  color: var(--green);
}

.decision-context-card.is-caution strong {
  color: var(--yellow);
}

.decision-context-card.is-negative strong {
  color: var(--red);
}

.rail-risk-grid article em {
  color: var(--text-muted);
  font-size: 0.58rem;
  font-style: normal;
  font-weight: 840;
  line-height: 1;
}

.rail-risk-vector-tooltip {
  display: grid;
  gap: 6px;
  max-width: 260px;
}

.rail-risk-vector-tooltip strong {
  font-size: 0.78rem;
}

.rail-risk-vector-tooltip p,
.rail-risk-vector-tooltip li {
  margin: 0;
  color: inherit;
  font-size: 0.68rem;
  line-height: 1.42;
}

.rail-risk-vector-tooltip ul {
  display: grid;
  gap: 4px;
  margin: 0;
  padding-left: 16px;
}

.rail-transition-card,
.rail-quality-card {
  align-content: start;
  gap: 6px;
  padding: 10px;
}

.rail-transition-card .rail-section-head,
.rail-quality-card .rail-section-head {
  min-height: 26px;
  margin-bottom: 2px;
}

.rail-transition-card .rail-section-head em,
.rail-quality-card .rail-section-head em {
  margin-left: auto;
  padding: 2px 7px;
  border: 1px solid rgba(102, 129, 162, 0.14);
  border-radius: 999px;
  color: var(--text-muted);
  font-size: 0.56rem;
  font-style: normal;
  font-weight: 900;
  line-height: 1.1;
}

.rail-transition-card p,
.rail-quality-card p {
  display: -webkit-box;
  margin: -2px 0 1px;
  overflow: hidden;
  color: var(--text-muted);
  font-size: 0.62rem;
  font-weight: 780;
  line-height: 1.38;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
}

.rail-transition-list,
.rail-quality-list {
  display: grid;
  gap: 5px;
}

.rail-transition-row,
.rail-quality-row {
  min-width: 0;
  min-height: 27px;
  display: grid;
  grid-template-columns: minmax(66px, 0.36fr) minmax(0, 1fr) 38px;
  align-items: center;
  gap: 7px;
  padding: 5px 7px;
  border: 1px solid rgba(118, 154, 190, 0.1);
  border-radius: 8px;
  background:
    linear-gradient(145deg, rgba(132, 167, 207, 0.066), rgba(132, 167, 207, 0.016)),
    rgba(8, 16, 26, 0.62);
}

.rail-transition-row span,
.rail-transition-row strong,
.rail-quality-row span,
.rail-quality-row strong {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.rail-transition-row span,
.rail-quality-row span {
  color: var(--text-secondary);
  font-size: 0.6rem;
  font-weight: 900;
}

.rail-transition-row strong,
.rail-quality-row strong {
  justify-self: end;
  color: var(--text-primary);
  font-size: 0.7rem;
  font-weight: 900;
  line-height: 1;
}

.rail-transition-row div,
.rail-quality-row div {
  height: 5px;
  overflow: hidden;
  border-radius: 999px;
  background: rgba(112, 129, 154, 0.14);
}

.rail-transition-row i,
.rail-quality-row i {
  display: block;
  height: 100%;
  border-radius: inherit;
  background: var(--blue);
}

.rail-transition-row.is-positive i,
