}

html[data-rportfolio-style="light"] .decision-rail .rail-quality-row,
html[data-rportfolio-style="light"] .decision-rail .rail-transition-row,
html[data-rportfolio-style="dark"] .decision-rail .rail-quality-row,
html[data-rportfolio-style="dark"] .decision-rail .rail-transition-row {
  display: grid !important;
  grid-template-columns: minmax(84px, 0.95fr) minmax(92px, 1.15fr) auto !important;
  align-items: center !important;
  gap: 8px !important;
  min-height: 30px !important;
  padding: 6px 8px !important;
  overflow: hidden !important;
  border: 1px solid var(--rp-final-line-soft) !important;
  border-radius: 9px !important;
  background: var(--rp-rail-card-soft) !important;
  box-shadow: none !important;
}

html[data-rportfolio-style="light"] .decision-rail .rail-quality-row div,
html[data-rportfolio-style="light"] .decision-rail .rail-transition-row div,
html[data-rportfolio-style="dark"] .decision-rail .rail-quality-row div,
html[data-rportfolio-style="dark"] .decision-rail .rail-transition-row div {
  min-width: 0 !important;
  height: 5px !important;
  overflow: hidden !important;
  border-radius: 999px !important;
  background: var(--rp-rail-meter-track) !important;
}

html[data-rportfolio-style="light"] .decision-rail .rail-quality-row span,
html[data-rportfolio-style="light"] .decision-rail .rail-transition-row span,
html[data-rportfolio-style="dark"] .decision-rail .rail-quality-row span,
html[data-rportfolio-style="dark"] .decision-rail .rail-transition-row span,
html[data-rportfolio-style="light"] .decision-rail .rail-section-head span,
html[data-rportfolio-style="dark"] .decision-rail .rail-section-head span,
html[data-rportfolio-style="light"] .decision-rail .evidence-summary-panel .panel-head h2,
html[data-rportfolio-style="dark"] .decision-rail .evidence-summary-panel .panel-head h2 {
  min-width: 0 !important;
  overflow: hidden !important;
  text-overflow: ellipsis !important;
  white-space: nowrap !important;
}

html[data-rportfolio-style="light"] .decision-rail .rail-quality-row strong,
html[data-rportfolio-style="light"] .decision-rail .rail-transition-row strong,
html[data-rportfolio-style="dark"] .decision-rail .rail-quality-row strong,
html[data-rportfolio-style="dark"] .decision-rail .rail-transition-row strong {
  justify-self: end !important;
  white-space: nowrap !important;
}

html[data-rportfolio-style="light"] .decision-rail .evidence-summary-panel.is-compact .evidence-columns,
html[data-rportfolio-style="dark"] .decision-rail .evidence-summary-panel.is-compact .evidence-columns {
  display: grid !important;
  grid-template-columns: 1fr !important;
  gap: 8px !important;
  min-width: 0 !important;
  overflow: hidden !important;
  border: 0 !important;
  background: transparent !important;
}

html[data-rportfolio-style="light"] .decision-rail .evidence-summary-panel.is-compact .evidence-columns > div,
html[data-rportfolio-style="dark"] .decision-rail .evidence-summary-panel.is-compact .evidence-columns > div {
  min-width: 0 !important;
  padding: 8px !important;
  overflow: hidden !important;
  border: 1px solid var(--rp-final-line-soft) !important;
  border-radius: 10px !important;
  background: var(--rp-rail-card-soft) !important;
}

html[data-rportfolio-style="light"] .decision-rail .evidence-line,
html[data-rportfolio-style="dark"] .decision-rail .evidence-line,
html[data-rportfolio-style="light"] .decision-rail .evidence-line p,
html[data-rportfolio-style="dark"] .decision-rail .evidence-line p {
  min-width: 0 !important;
  overflow: hidden !important;
  text-overflow: ellipsis !important;
  white-space: nowrap !important;
}

html[data-rportfolio-style="light"] .workbench-panel .tab-strip,
html[data-rportfolio-style="dark"] .workbench-panel .tab-strip {
  position: relative !important;
  display: grid !important;
  grid-template-columns: repeat(5, minmax(0, 1fr)) !important;
  align-items: center !important;
  gap: 4px !important;
  width: 100% !important;
  min-height: calc(var(--rp-tab-height) + 6px) !important;
  height: auto !important;
  margin: 0 0 12px !important;
  padding: 3px !important;
  overflow: visible !important;
  border: 1px solid var(--rp-final-line-soft) !important;
  border-radius: 12px !important;
  background: var(--rp-tab-bg) !important;
  box-shadow: none !important;
}

html[data-rportfolio-style="light"] .workbench-panel .tab-strip button,
html[data-rportfolio-style="dark"] .workbench-panel .tab-strip button {
  display: flex !important;
  align-items: center !important;
  justify-content: center !important;
  min-width: 0 !important;
  width: 100% !important;
  min-height: var(--rp-tab-height) !important;
  height: var(--rp-tab-height) !important;
  margin: 0 !important;
  padding: 0 10px !important;
  overflow: hidden !important;
  border: 0 !important;
  border-radius: 10px !important;
  color: var(--rp-muted) !important;
  line-height: 1 !important;
  white-space: nowrap !important;
  text-overflow: ellipsis !important;
  background: transparent !important;
  box-shadow: none !important;
}

html[data-rportfolio-style="light"] .workbench-panel .tab-strip button.is-active,
html[data-rportfolio-style="dark"] .workbench-panel .tab-strip button.is-active {
  color: var(--rp-tab-active-text) !important;
  background: var(--rp-tab-active-bg) !important;
  box-shadow: none !important;
}

html[data-rportfolio-style="light"] .workbench-panel .tab-strip button::after,
html[data-rportfolio-style="dark"] .workbench-panel .tab-strip button::after {
  display: none !important;
}

/* Quant Lab trading-cockpit pass. */
html[data-rportfolio-style="light"] .workspace-area > .quant-lab-page,
html[data-rportfolio-style="dark"] .workspace-area > .quant-lab-page {
  height: 100% !important;
  min-height: 0 !important;
  padding: 0 !important;
}

.quant-lab-page {
  position: relative;
  display: grid;
  grid-template-rows: 62px minmax(0, 1fr);
  gap: 0;
  min-width: 0;
  overflow: hidden;
  color: var(--rp-text);
  isolation: isolate;
  background:
    linear-gradient(135deg, rgba(255, 255, 255, 0.055), transparent 34%),
    linear-gradient(180deg, rgba(20, 27, 39, 0.54), rgba(8, 12, 18, 0.18));
}

.quant-lab-page::before {
  position: absolute;
  inset: 0;
  z-index: -1;
  content: "";
  pointer-events: none;
  background:
    linear-gradient(90deg, rgba(255, 255, 255, 0.028) 1px, transparent 1px),
    linear-gradient(180deg, rgba(255, 255, 255, 0.018) 1px, transparent 1px);
  background-size: 44px 44px;
  mask-image: linear-gradient(180deg, rgba(0, 0, 0, 0.8), transparent 72%);
}

.quant-trading-header {
  min-width: 0;
  min-height: 0;
  display: grid;
  grid-template-columns: minmax(190px, 0.7fr) minmax(420px, 1.4fr) auto;
  align-items: center;
  gap: 12px;
  padding: 8px 16px;
  border-bottom: 1px solid var(--rp-final-line-soft);
  background: rgba(12, 18, 27, 0.42);
  backdrop-filter: blur(22px) saturate(1.35);
}

.quant-terminal-title {
  min-width: 0;
  display: grid;
  gap: 3px;
}

.quant-terminal-title span,
.quant-panel-title span,
.quant-section-head span,
.quant-mini-head span,
.quant-param span,
.quant-metric span,
.quant-status-pill span,
.quant-ticket-head span,
.quant-pipeline-step span,
.quant-risk-rule span {
  min-width: 0;
  overflow: hidden;
  color: var(--rp-muted);
  font-size: 0.67rem;
  font-weight: 780;
  letter-spacing: 0;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.quant-terminal-title span {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  color: var(--rp-accent);
}

.quant-terminal-title h1 {
  margin: 0;
  overflow: hidden;
  color: var(--rp-text);
  font-size: 1.28rem;
  line-height: 1.05;
  letter-spacing: 0;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.quant-terminal-status {
  min-width: 0;
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 8px;
}

.quant-status-pill,
.quant-param,
.quant-metric,
.quant-pipeline-step,
.quant-risk-rule {
  min-width: 0;
  padding: 8px 9px;
  display: grid;
  gap: 4px;
  border: 1px solid rgba(226, 238, 251, 0.09);
  border-left: 3px solid var(--rp-accent);
  border-radius: 10px;
  background: rgba(255, 255, 255, 0.045);
  backdrop-filter: blur(16px) saturate(1.22);
}

.quant-status-pill strong,
.quant-param strong,
.quant-metric strong,
.quant-pipeline-step strong,
.quant-risk-rule strong {
  min-width: 0;
  overflow: hidden;
  color: var(--rp-text);
  font-size: 0.78rem;
  line-height: 1.12;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.quant-status-pill.is-positive,
.quant-param.is-positive,
.quant-metric.is-positive,
.quant-pipeline-step.is-positive,
.quant-risk-rule.is-positive {
  border-left-color: var(--green);
}

.quant-status-pill.is-caution,
.quant-param.is-caution,
.quant-metric.is-caution,
.quant-pipeline-step.is-caution,
.quant-risk-rule.is-caution {
  border-left-color: var(--yellow);
}

.quant-status-pill.is-negative,
.quant-param.is-negative,
.quant-metric.is-negative,
.quant-pipeline-step.is-negative,
.quant-risk-rule.is-negative {
  border-left-color: var(--red);
}

.quant-run-controls {
  display: inline-flex;
  align-items: center;
  justify-content: flex-end;
  gap: 8px;
}

.quant-run-controls button,
.quant-paper-button,
.quant-empty-state button {
  min-height: 32px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding: 0 11px;
  border: 1px solid var(--rp-final-line-soft);
  border-radius: 9px;
  color: var(--rp-text);
  background: var(--rp-final-surface);
  cursor: pointer;
}

.quant-run-controls button:hover,
.quant-paper-button:hover,
.quant-empty-state button:hover {
  border-color: var(--rp-accent-border);
  background: var(--rp-control-hover);
}

.quant-run-controls button.is-primary,
.quant-paper-button,
.quant-empty-state button {
  color: var(--rp-accent-text);
  border-color: var(--rp-accent-border);
  background: var(--rp-accent);
}

.quant-trading-grid {
  min-height: 0;
  display: grid;
  grid-template-columns: 252px minmax(0, 1fr) var(--rp-rail-width);
  gap: 0;
  overflow: hidden;
}

.quant-trading-grid.is-execution-collapsed {
  grid-template-columns: 252px minmax(0, 1fr);
}

.quant-control-panel,
.quant-market-stage,
.quant-execution-rail {
  min-width: 0;
  min-height: 0;
  overflow: hidden auto;
}

.quant-control-panel {
  padding: 12px;
  display: grid;
  align-content: start;
  gap: 10px;
  border-right: 1px solid var(--rp-final-line-soft);
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.055), rgba(255, 255, 255, 0.014)),
    rgba(12, 17, 25, 0.54);
  backdrop-filter: blur(22px) saturate(1.25);
}

.quant-market-stage {
  padding: 12px;
  display: grid;
  grid-template-rows: minmax(420px, 1fr) auto;
  align-content: stretch;
  gap: 12px;
}

.quant-panel-title,
.quant-section-head,
.quant-mini-head,
.quant-ticket-head {
  min-width: 0;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
}

.quant-panel-title {
  justify-content: flex-start;
}

.quant-panel-title > svg,
.quant-section-head > svg {
  flex: 0 0 auto;
  color: var(--rp-accent);
  font-size: 1.02rem;
}

.quant-panel-title > div,
.quant-section-head > div {
  min-width: 0;
  display: grid;
  gap: 2px;
}

.quant-panel-title strong,
.quant-section-head strong,
.quant-mini-head strong,
.quant-ticket-head strong {
  min-width: 0;
  overflow: hidden;
  color: var(--rp-text);
  font-size: 0.9rem;
  line-height: 1.12;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.quant-mode-switch {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 6px;
  padding: 4px;
  border: 1px solid var(--rp-final-line-soft);
  border-radius: 11px;
  background: var(--rp-final-surface-soft);
}

.quant-mode-switch button {
  min-width: 0;
  min-height: 42px;
  padding: 7px;
  display: grid;
  gap: 2px;
  border: 0;
  border-radius: 8px;
  color: var(--rp-muted);
  background: transparent;
  cursor: pointer;
}

.quant-mode-switch button.is-active {
  color: var(--rp-text);
  background: var(--rp-final-surface);
}

.quant-mode-switch strong,
.quant-mode-switch span {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.quant-mode-switch strong {
  font-size: 0.78rem;
}

.quant-mode-switch span {
  font-size: 0.66rem;
}

.quant-strategy-list {
  display: grid;
  gap: 7px;
}

.quant-strategy-list button {
  width: 100%;
  min-width: 0;
  min-height: 42px;
  padding: 7px 9px;
  display: grid;
  grid-template-columns: 44px minmax(0, 1fr) 42px;
  align-items: center;
  gap: 7px;
  border: 1px solid var(--rp-final-line-soft);
  border-radius: 10px;
  color: var(--rp-text);
  background: var(--rp-final-surface-soft);
  cursor: pointer;
}

.quant-strategy-list button:hover {
  border-color: var(--rp-accent-border);
  background: var(--rp-final-surface);
}

.quant-strategy-list button.is-active {
  color: var(--rp-accent-text);
  border-color: var(--rp-accent-border);
  background: var(--rp-accent);
}

html[data-rportfolio-style="dark"] .quant-strategy-list button.is-active {
  color: #dcecff;
  background: linear-gradient(180deg, rgba(71, 91, 116, 0.95), rgba(46, 58, 74, 0.95));
}

.quant-strategy-list span,
.quant-strategy-list em,
.quant-strategy-list strong {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.quant-strategy-list span,
.quant-strategy-list em {
  color: currentColor;
  font-size: 0.64rem;
  font-style: normal;
  font-weight: 760;
  opacity: 0.72;
}

.quant-strategy-list strong {
  font-size: 0.8rem;
}

.quant-config-actions {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 7px;
}

.quant-config-actions button,
.quant-rail-actions button,
.quant-dialog-head button,
.quant-bridge-status-list .quant-mini-head button {
  min-width: 0;
  min-height: 31px;
  padding: 0 9px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 5px;
  border: 1px solid var(--rp-final-line-soft);
  border-radius: 8px;
  color: var(--rp-text);
  background: var(--rp-final-surface-soft);
  cursor: pointer;
}

.quant-config-actions button:hover,
.quant-rail-actions button:hover,
.quant-dialog-head button:hover,
.quant-bridge-status-list .quant-mini-head button:hover {
  border-color: var(--rp-accent-border);
  background: var(--rp-control-hover);
}

.quant-config-actions span {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
