}

@media (max-width: 1080px) {
  .quant-trading-header,
  .quant-chart-head,
  .quant-trade-lower-grid {
    grid-template-columns: minmax(0, 1fr);
  }

  .quant-trading-grid {
    grid-template-columns: 204px minmax(0, 1fr) minmax(280px, 31vw);
  }

  .quant-trading-grid.is-execution-collapsed {
    grid-template-columns: 204px minmax(0, 1fr);
  }

  .quant-terminal-status,
  .quant-chart-stats,
  .quant-evidence-row,
  .quant-signal-grid,
  .quant-pipeline-track {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .quant-control-panel {
    border: 0;
    border-top: 1px solid var(--rp-final-line-soft);
  }
}

