.quant-evidence-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 8px;
}

.quant-evidence-grid article {
  padding: 12px;
  display: grid;
  gap: 6px;
}

.quant-permission-card {
  padding: 12px;
  display: grid;
  grid-template-columns: 28px minmax(0, 1fr);
  gap: 10px;
}

.quant-permission-card > svg {
  color: var(--rp-accent);
  font-size: 1.2rem;
}

.quant-permission-card div {
  min-width: 0;
  display: grid;
  gap: 5px;
}

.quant-permission-card strong {
  min-width: 0;
  overflow: hidden;
  color: var(--rp-text);
  font-size: 0.92rem;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.quant-order-list {
  display: grid;
  gap: 8px;
}

.quant-order-list article {
  padding: 11px;
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 8px 10px;
  border-left: 3px solid var(--rp-accent);
}

.quant-order-list article div {
  min-width: 0;
  display: grid;
  gap: 4px;
}

.quant-order-list article strong {
  min-width: 0;
  overflow: hidden;
  color: var(--rp-text);
  font-size: 0.88rem;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.quant-order-list article p {
  grid-column: 1 / -1;
}

.quant-no-orders {
  min-height: 136px;
  padding: 18px 14px;
  display: grid;
  place-items: center;
  gap: 7px;
  text-align: center;
  border: 1px dashed var(--rp-line);
  border-radius: 12px;
  color: var(--rp-muted);
  background: var(--rp-control-bg);
}

.quant-no-orders svg {
  color: var(--rp-accent);
  font-size: 1.5rem;
}

.quant-no-orders strong {
  color: var(--rp-text);
  font-size: 0.92rem;
}

.quant-no-orders span {
  max-width: 220px;
  font-size: 0.74rem;
  line-height: 1.4;
}

.quant-log-panel {
  display: grid;
  gap: 8px;
}

.quant-log-panel article {
  padding: 9px 10px;
  display: grid;
  grid-template-columns: 48px minmax(0, 1fr);
  gap: 8px;
  border-left: 3px solid var(--rp-accent);
}

.quant-log-panel article p {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.quant-empty-state {
  min-height: 360px;
  padding: 30px;
  border-radius: 14px;
  display: grid;
  place-items: center;
  align-content: center;
  gap: 12px;
  text-align: center;
}

.quant-empty-state svg {
  color: var(--rp-accent);
  font-size: 2rem;
}

.quant-empty-state div {
  display: grid;
  gap: 6px;
}

.quant-empty-state strong {
  color: var(--rp-text);
  font-size: 1.08rem;
}

.quant-empty-state button {
  min-height: 34px;
  padding: 0 14px;
  border: 1px solid var(--rp-accent-border);
  border-radius: 10px;
